-- >>> 01_Schemas.sql
/*
 * DIRECT Framework - Snowflake edition
 * 01 Schemas
 *
 * The repository lives in the database that the deployment passes as the
 * `database` variable (Snowflake CLI: snow sql -f <file> -D database=<name>).
 * Every object is fully qualified, so the scripts do not depend on the session
 * context. The schema names follow the SQL Server edition: OMD for the
 * repository, OMD_METADATA for the reference data and settings, OMD_PROCESSING
 * for the processing views and OMD_REPORTING for the reporting views.
 */

CREATE DATABASE IF NOT EXISTS <% database %>;

CREATE SCHEMA IF NOT EXISTS <% database %>.OMD
  COMMENT = 'DIRECT Framework repository: Batches, Modules, their instances, events and load windows.';

CREATE SCHEMA IF NOT EXISTS <% database %>.OMD_METADATA
  COMMENT = 'DIRECT Framework reference data and settings.';

CREATE SCHEMA IF NOT EXISTS <% database %>.OMD_PROCESSING
  COMMENT = 'DIRECT Framework processing views (queues, hierarchy).';

CREATE SCHEMA IF NOT EXISTS <% database %>.OMD_REPORTING
  COMMENT = 'DIRECT Framework reporting views (execution logs, exceptions).';

-- >>> 02_Tables.sql
/*
 * DIRECT Framework - Snowflake edition
 * 02 Tables and sequences
 *
 * The tables keep the names and columns of the SQL Server edition, in Snowflake
 * types. Identity columns are replaced by sequences; the procedures take the
 * next value explicitly so that the new identifier is known to the caller.
 * The scripts can be run again: existing tables and their data are kept.
 */

-- Reference data

CREATE TABLE IF NOT EXISTS <% database %>.OMD_METADATA.LAYER
(
    LAYER_CODE          VARCHAR(100)   NOT NULL,
    LAYER_DESCRIPTION   VARCHAR(4000),
    CONSTRAINT PK_LAYER PRIMARY KEY (LAYER_CODE)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD_METADATA.AREA
(
    AREA_CODE           VARCHAR(100)   NOT NULL,
    LAYER_CODE          VARCHAR(100)   NOT NULL,
    AREA_DESCRIPTION    VARCHAR(4000),
    CONSTRAINT PK_AREA PRIMARY KEY (AREA_CODE)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD_METADATA.EVENT_TYPE
(
    EVENT_TYPE_CODE         NUMBER(38,0)   NOT NULL,
    EVENT_TYPE_DESCRIPTION  VARCHAR(4000),
    CONSTRAINT PK_EVENT_TYPE PRIMARY KEY (EVENT_TYPE_CODE)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD_METADATA.EXECUTION_STATUS
(
    EXECUTION_STATUS_CODE         VARCHAR(100)   NOT NULL,
    EXECUTION_STATUS_DESCRIPTION  VARCHAR(4000),
    CONSTRAINT PK_EXECUTION_STATUS PRIMARY KEY (EXECUTION_STATUS_CODE)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD_METADATA.INTERNAL_PROCESSING_STATUS
(
    INTERNAL_PROCESSING_STATUS_CODE         VARCHAR(100)   NOT NULL,
    INTERNAL_PROCESSING_STATUS_DESCRIPTION  VARCHAR(4000),
    CONSTRAINT PK_INTERNAL_PROCESSING_STATUS PRIMARY KEY (INTERNAL_PROCESSING_STATUS_CODE)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD_METADATA.NEXT_RUN_STATUS
(
    NEXT_RUN_STATUS_CODE         VARCHAR(100)   NOT NULL,
    NEXT_RUN_STATUS_DESCRIPTION  VARCHAR(4000),
    CONSTRAINT PK_NEXT_RUN_STATUS PRIMARY KEY (NEXT_RUN_STATUS_CODE)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD_METADATA.FREQUENCY
(
    FREQUENCY_CODE         VARCHAR(100)   NOT NULL,
    FREQUENCY_DESCRIPTION  VARCHAR(4000),
    CONSTRAINT PK_FREQUENCY PRIMARY KEY (FREQUENCY_CODE)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD_METADATA.FRAMEWORK_METADATA
(
    CODE              VARCHAR(100)   NOT NULL,
    VALUE             VARCHAR(4000),
    "GROUP"           VARCHAR(100)   NOT NULL,
    DESCRIPTION       VARCHAR(4000),
    ACTIVE_INDICATOR  VARCHAR(1)     NOT NULL DEFAULT 'Y',
    CONSTRAINT PK_FRAMEWORK_METADATA PRIMARY KEY (CODE)
);

-- Sequences

CREATE SEQUENCE IF NOT EXISTS <% database %>.OMD.BATCH_SEQ START = 1 INCREMENT = 1 ORDER;
CREATE SEQUENCE IF NOT EXISTS <% database %>.OMD.BATCH_INSTANCE_SEQ START = 1 INCREMENT = 1 ORDER;
CREATE SEQUENCE IF NOT EXISTS <% database %>.OMD.MODULE_SEQ START = 1 INCREMENT = 1 ORDER;
CREATE SEQUENCE IF NOT EXISTS <% database %>.OMD.MODULE_INSTANCE_SEQ START = 1 INCREMENT = 1 ORDER;
CREATE SEQUENCE IF NOT EXISTS <% database %>.OMD.EVENT_LOG_SEQ START = 1 INCREMENT = 1 ORDER;
CREATE SEQUENCE IF NOT EXISTS <% database %>.OMD.SOURCE_CONTROL_SEQ START = 1 INCREMENT = 1 ORDER;

-- Repository

CREATE TABLE IF NOT EXISTS <% database %>.OMD.BATCH
(
    BATCH_ID           NUMBER(38,0)   NOT NULL,
    BATCH_CODE         VARCHAR(500)   NOT NULL,
    BATCH_TYPE         VARCHAR(100),
    FREQUENCY_CODE     VARCHAR(100)   NOT NULL DEFAULT 'On-demand',
    ACTIVE_INDICATOR   VARCHAR(1)     NOT NULL DEFAULT 'Y',
    BATCH_DESCRIPTION  VARCHAR(4000),
    CONSTRAINT PK_BATCH PRIMARY KEY (BATCH_ID),
    CONSTRAINT UK_BATCH_CODE UNIQUE (BATCH_CODE)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD.BATCH_HIERARCHY
(
    PARENT_BATCH_ID    NUMBER(38,0)   NOT NULL,
    BATCH_ID           NUMBER(38,0)   NOT NULL,
    SEQUENCE           NUMBER(38,0)   NOT NULL DEFAULT 0,
    ACTIVE_INDICATOR   VARCHAR(1)     NOT NULL DEFAULT 'Y',
    CONSTRAINT PK_BATCH_HIERARCHY PRIMARY KEY (PARENT_BATCH_ID, BATCH_ID)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD.BATCH_INSTANCE
(
    BATCH_INSTANCE_ID         NUMBER(38,0)    NOT NULL,
    BATCH_ID                  NUMBER(38,0)    NOT NULL,
    PARENT_BATCH_INSTANCE_ID  NUMBER(38,0)    NOT NULL DEFAULT 0,
    START_TIMESTAMP           TIMESTAMP_NTZ   NOT NULL,
    END_TIMESTAMP             TIMESTAMP_NTZ,
    INTERNAL_PROCESSING_CODE  VARCHAR(100)    NOT NULL,
    NEXT_RUN_STATUS_CODE      VARCHAR(100)    NOT NULL,
    EXECUTION_STATUS_CODE     VARCHAR(100)    NOT NULL,
    EXECUTION_CONTEXT         VARCHAR(4000),
    CONSTRAINT PK_BATCH_INSTANCE PRIMARY KEY (BATCH_INSTANCE_ID)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD.MODULE
(
    MODULE_ID           NUMBER(38,0)   NOT NULL,
    MODULE_CODE         VARCHAR(500)   NOT NULL,
    MODULE_TYPE         VARCHAR(100)   NOT NULL DEFAULT 'DataLogistics',
    DATA_OBJECT_SOURCE  VARCHAR(1000)  NOT NULL DEFAULT 'N/A',
    DATA_OBJECT_TARGET  VARCHAR(1000)  NOT NULL DEFAULT 'N/A',
    AREA_CODE           VARCHAR(100)   NOT NULL DEFAULT 'MAINT',
    FREQUENCY_CODE      VARCHAR(100)   NOT NULL DEFAULT 'On-demand',
    ACTIVE_INDICATOR    VARCHAR(1)     NOT NULL DEFAULT 'Y',
    MODULE_DESCRIPTION  VARCHAR(4000),
    EXECUTABLE          VARCHAR,
    CONSTRAINT PK_MODULE PRIMARY KEY (MODULE_ID),
    CONSTRAINT UK_MODULE_CODE UNIQUE (MODULE_CODE)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD.BATCH_MODULE
(
    BATCH_ID           NUMBER(38,0)   NOT NULL,
    MODULE_ID          NUMBER(38,0)   NOT NULL,
    SEQUENCE           NUMBER(38,0)   NOT NULL DEFAULT 0,
    ACTIVE_INDICATOR   VARCHAR(1)     NOT NULL DEFAULT 'Y',
    CONSTRAINT PK_BATCH_MODULE PRIMARY KEY (BATCH_ID, MODULE_ID)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD.MODULE_INSTANCE
(
    MODULE_INSTANCE_ID        NUMBER(38,0)    NOT NULL,
    MODULE_ID                 NUMBER(38,0)    NOT NULL,
    BATCH_INSTANCE_ID         NUMBER(38,0)    NOT NULL DEFAULT 0,
    START_TIMESTAMP           TIMESTAMP_NTZ   NOT NULL,
    END_TIMESTAMP             TIMESTAMP_NTZ,
    INTERNAL_PROCESSING_CODE  VARCHAR(100)    NOT NULL,
    NEXT_RUN_STATUS_CODE      VARCHAR(100)    NOT NULL,
    EXECUTION_STATUS_CODE     VARCHAR(100)    NOT NULL,
    EXECUTION_CONTEXT         VARCHAR(4000),
    ROWS_INPUT                NUMBER(38,0),
    ROWS_INSERTED             NUMBER(38,0),
    ROWS_UPDATED              NUMBER(38,0),
    ROWS_DELETED              NUMBER(38,0),
    ROWS_DISCARDED            NUMBER(38,0),
    ROWS_REJECTED             NUMBER(38,0),
    EXECUTED_CODE_CHECKSUM    VARCHAR(128),
    CONSTRAINT PK_MODULE_INSTANCE PRIMARY KEY (MODULE_INSTANCE_ID)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD.MODULE_INSTANCE_EXECUTED_CODE
(
    CHECKSUM        VARCHAR(128)   NOT NULL,
    EXECUTED_CODE   VARCHAR,
    CONSTRAINT PK_MODULE_INSTANCE_EXECUTED_CODE PRIMARY KEY (CHECKSUM)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD.EVENT_LOG
(
    EVENT_ID            NUMBER(38,0)    NOT NULL,
    BATCH_INSTANCE_ID   NUMBER(38,0)    NOT NULL DEFAULT 0,
    MODULE_INSTANCE_ID  NUMBER(38,0)    NOT NULL DEFAULT 0,
    EVENT_TYPE_CODE     NUMBER(38,0)    NOT NULL DEFAULT 2,
    EVENT_TIMESTAMP     TIMESTAMP_NTZ   NOT NULL,
    EVENT_RETURN_CODE   VARCHAR(100),
    EVENT_DETAIL        VARCHAR(4000),
    ERROR_BITMAP        NUMBER(38,0),
    CONSTRAINT PK_EVENT_LOG PRIMARY KEY (EVENT_ID)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD.SOURCE_CONTROL
(
    SOURCE_CONTROL_ID   NUMBER(38,0)    NOT NULL,
    MODULE_ID           NUMBER(38,0)    NOT NULL,
    MODULE_INSTANCE_ID  NUMBER(38,0)    NOT NULL,
    INSERT_TIMESTAMP    TIMESTAMP_NTZ   NOT NULL,
    START_VALUE         VARCHAR(100),
    END_VALUE           VARCHAR(100),
    CONSTRAINT PK_SOURCE_CONTROL PRIMARY KEY (SOURCE_CONTROL_ID)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD.BATCH_PARAMETER
(
    BATCH_ID          NUMBER(38,0)   NOT NULL,
    PARAMETER_CODE    VARCHAR(100)   NOT NULL,
    PARAMETER_VALUE   VARCHAR(4000),
    CONSTRAINT PK_BATCH_PARAMETER PRIMARY KEY (BATCH_ID, PARAMETER_CODE)
);

CREATE TABLE IF NOT EXISTS <% database %>.OMD.MODULE_PARAMETER
(
    MODULE_ID         NUMBER(38,0)   NOT NULL,
    PARAMETER_CODE    VARCHAR(100)   NOT NULL,
    PARAMETER_VALUE   VARCHAR(4000),
    CONSTRAINT PK_MODULE_PARAMETER PRIMARY KEY (MODULE_ID, PARAMETER_CODE)
);

-- >>> 03_ReferenceData.sql
/*
 * DIRECT Framework - Snowflake edition
 * 03 Reference data and settings
 *
 * The reference data is merged, so the script can be run again. The settings
 * keep their value when they already exist; only new settings are added.
 */

MERGE INTO <% database %>.OMD_METADATA.LAYER AS tgt
USING (SELECT * FROM VALUES
    ('Integration',  'The Integration Layer'),
    ('Presentation', 'The Presentation Layer'),
    ('Staging',      'The Staging Layer'),
    ('Maintenance',  'Internal Data Solution')
  AS src (LAYER_CODE, LAYER_DESCRIPTION)) AS src
ON tgt.LAYER_CODE = src.LAYER_CODE
WHEN MATCHED THEN UPDATE SET LAYER_DESCRIPTION = src.LAYER_DESCRIPTION
WHEN NOT MATCHED THEN INSERT (LAYER_CODE, LAYER_DESCRIPTION) VALUES (src.LAYER_CODE, src.LAYER_DESCRIPTION);

MERGE INTO <% database %>.OMD_METADATA.AREA AS tgt
USING (SELECT * FROM VALUES
    ('HELPER', 'Presentation', 'The Helper Area'),
    ('INT',    'Integration',  'The Base Integration Area'),
    ('INTPR',  'Integration',  'The Derived Integration Area'),
    ('LND',    'Staging',      'The Landing Area of the Staging Layer'),
    ('MAINT',  'Maintenance',  'Internal Data Solution'),
    ('PRES',   'Presentation', 'The Access Area'),
    ('PSA',    'Staging',      'The Persistent Staging Area'),
    ('STG',    'Staging',      'The Staging Area of the Staging Layer'),
    ('SYNC',   'Staging',      'Synchronization of the production History Area of the Staging Layer')
  AS src (AREA_CODE, LAYER_CODE, AREA_DESCRIPTION)) AS src
ON tgt.AREA_CODE = src.AREA_CODE
WHEN MATCHED THEN UPDATE SET LAYER_CODE = src.LAYER_CODE, AREA_DESCRIPTION = src.AREA_DESCRIPTION
WHEN NOT MATCHED THEN INSERT (AREA_CODE, LAYER_CODE, AREA_DESCRIPTION) VALUES (src.AREA_CODE, src.LAYER_CODE, src.AREA_DESCRIPTION);

MERGE INTO <% database %>.OMD_METADATA.EVENT_TYPE AS tgt
USING (SELECT * FROM VALUES
    (1, 'Infrastructure error.'),
    (2, 'Internal data integration process error or system generated event.'),
    (3, 'Custom exception handling that has been implemented in code (Error Bitmaps).')
  AS src (EVENT_TYPE_CODE, EVENT_TYPE_DESCRIPTION)) AS src
ON tgt.EVENT_TYPE_CODE = src.EVENT_TYPE_CODE
WHEN MATCHED THEN UPDATE SET EVENT_TYPE_DESCRIPTION = src.EVENT_TYPE_DESCRIPTION
WHEN NOT MATCHED THEN INSERT (EVENT_TYPE_CODE, EVENT_TYPE_DESCRIPTION) VALUES (src.EVENT_TYPE_CODE, src.EVENT_TYPE_DESCRIPTION);

MERGE INTO <% database %>.OMD_METADATA.EXECUTION_STATUS AS tgt
USING (SELECT * FROM VALUES
    ('Aborted',   'The instance was attempted but could not start, typically because another instance of the same Batch or Module is already running, or because the Module was run from a Batch it is not registered for. No data was processed.'),
    ('Cancelled', 'The instance was attempted but the framework found that it was not necessary to run it: the Batch, Module or Batch/Module relationship is inactive, or the Module completed successfully in an earlier run of a Batch that is being restarted.'),
    ('Executing', 'The instance is running. This is a transient state; it is replaced by an end state when the instance completes.'),
    ('Failed',    'The instance completed with failures.'),
    ('Succeeded', 'The instance completed successfully.')
  AS src (EXECUTION_STATUS_CODE, EXECUTION_STATUS_DESCRIPTION)) AS src
ON tgt.EXECUTION_STATUS_CODE = src.EXECUTION_STATUS_CODE
WHEN MATCHED THEN UPDATE SET EXECUTION_STATUS_DESCRIPTION = src.EXECUTION_STATUS_DESCRIPTION
WHEN NOT MATCHED THEN INSERT (EXECUTION_STATUS_CODE, EXECUTION_STATUS_DESCRIPTION) VALUES (src.EXECUTION_STATUS_CODE, src.EXECUTION_STATUS_DESCRIPTION);

MERGE INTO <% database %>.OMD_METADATA.INTERNAL_PROCESSING_STATUS AS tgt
USING (SELECT * FROM VALUES
    ('Abort',    'Another instance of the same Batch or Module is already running, or the configuration is inconsistent. All further processing stops; the Execution Status becomes Aborted.'),
    ('Cancel',   'The evaluation found that it is not necessary to run this instance. All further processing stops; the Execution Status becomes Cancelled.'),
    ('Proceed',  'The instance can continue to the next step. This is the default value; every step continues only when the status is Proceed.'),
    ('Rollback', 'Set temporarily during the rollback of earlier failed instances. After the rollback the status is set to Proceed again.')
  AS src (INTERNAL_PROCESSING_STATUS_CODE, INTERNAL_PROCESSING_STATUS_DESCRIPTION)) AS src
ON tgt.INTERNAL_PROCESSING_STATUS_CODE = src.INTERNAL_PROCESSING_STATUS_CODE
WHEN MATCHED THEN UPDATE SET INTERNAL_PROCESSING_STATUS_DESCRIPTION = src.INTERNAL_PROCESSING_STATUS_DESCRIPTION
WHEN NOT MATCHED THEN INSERT (INTERNAL_PROCESSING_STATUS_CODE, INTERNAL_PROCESSING_STATUS_DESCRIPTION) VALUES (src.INTERNAL_PROCESSING_STATUS_CODE, src.INTERNAL_PROCESSING_STATUS_DESCRIPTION);

MERGE INTO <% database %>.OMD_METADATA.NEXT_RUN_STATUS AS tgt
USING (SELECT * FROM VALUES
    ('Cancel',   'Set by an administrator to skip the next run of the Batch or Module once.'),
    ('Proceed',  'The next run continues normally. This is the default value.'),
    ('Rollback', 'Set when an instance fails, so that the next run rolls back the data of the failed instance before it continues. An administrator can set it to force a rollback.')
  AS src (NEXT_RUN_STATUS_CODE, NEXT_RUN_STATUS_DESCRIPTION)) AS src
ON tgt.NEXT_RUN_STATUS_CODE = src.NEXT_RUN_STATUS_CODE
WHEN MATCHED THEN UPDATE SET NEXT_RUN_STATUS_DESCRIPTION = src.NEXT_RUN_STATUS_DESCRIPTION
WHEN NOT MATCHED THEN INSERT (NEXT_RUN_STATUS_CODE, NEXT_RUN_STATUS_DESCRIPTION) VALUES (src.NEXT_RUN_STATUS_CODE, src.NEXT_RUN_STATUS_DESCRIPTION);

MERGE INTO <% database %>.OMD_METADATA.FREQUENCY AS tgt
USING (SELECT * FROM VALUES
    ('Continuous', 'Continuously running integration processing unit.'),
    ('Triggered',  'Event triggered processing unit.'),
    ('On-demand',  'On-demand processing unit.'),
    ('Scheduled',  'Scheduled processing unit.')
  AS src (FREQUENCY_CODE, FREQUENCY_DESCRIPTION)) AS src
ON tgt.FREQUENCY_CODE = src.FREQUENCY_CODE
WHEN MATCHED THEN UPDATE SET FREQUENCY_DESCRIPTION = src.FREQUENCY_DESCRIPTION
WHEN NOT MATCHED THEN INSERT (FREQUENCY_CODE, FREQUENCY_DESCRIPTION) VALUES (src.FREQUENCY_CODE, src.FREQUENCY_DESCRIPTION);

-- Settings. Existing values are kept, except the version.
MERGE INTO <% database %>.OMD_METADATA.FRAMEWORK_METADATA AS tgt
USING (SELECT * FROM VALUES
    ('DIRECT_VERSION',                 '2.2.0',                      'SYSTEM_METADATA', 'The version of the DIRECT Framework this repository was deployed from.', 'Y'),
    ('DIRECT_EDITION',                 'Snowflake',                  'SYSTEM_METADATA', 'The edition of the DIRECT Framework this repository was deployed from.', 'Y'),
    ('LOG_TO_EVENT_LOG',               'Y',                          'SETTINGS', 'Write informational messages of the procedures to the event log (Y) or only errors (N).', 'Y'),
    ('THROW_ON_FAILURE',               'Y',                          'SETTINGS', 'Raise an error at the end of a top-level RUN_BATCH, or of a stand-alone RUN_MODULE, when a Module failed (Y), so that a Task run or a script stops, or return the result quietly (N). The bookkeeping is complete in both cases.', 'Y'),
    ('FAIL_BATCH_ON_MODULE_FAILURE',   'Y',                          'SETTINGS', 'Fail the Batch Instance when one of its Module Instances failed.', 'Y'),
    ('STOP_BATCH_ON_MODULE_FAILURE',   'Y',                          'SETTINGS', 'Stop running the remaining Modules and child Batches of a Batch after a Module failed (Y), or run them anyway (N).', 'Y'),
    ('AUTO_REGISTER_BATCHES',          'Y',                          'SETTINGS', 'Register a Batch that is run but not registered.', 'Y'),
    ('AUTO_REGISTER_MODULES',          'Y',                          'SETTINGS', 'Register a Module that is run but not registered.', 'Y'),
    ('AUTO_REGISTER_RELATIONSHIPS',    'Y',                          'SETTINGS', 'Register a Batch/Module or Batch/parent Batch relationship that is used but not registered.', 'Y'),
    ('MODULE_INSTANCE_ID_COLUMN_NAME', 'MODULE_INSTANCE_ID',         'SETTINGS', 'The column in the target data objects that holds the Module Instance Id of the run that inserted the row. The rollback deletes by this column.', 'Y'),
    ('DEFAULT_START_VALUE',            '1900-01-01 00:00:00.0000000', 'SETTINGS', 'The load window start value for a Module that has no load window recorded yet.', 'Y'),
    ('LOAD_WINDOW_ATTRIBUTE_NAME',     '',                           'SETTINGS', 'The attribute whose maximum value in the source data object ends the load window of a Module. Empty: the load window ends at the start of the Module Instance.', 'Y'),
    ('TIMESTAMP_FORMAT',               'YYYY-MM-DD HH24:MI:SS.FF7',  'SETTINGS', 'The format of timestamps in load window values and messages.', 'Y'),
    ('QUEUE_WAREHOUSE_SIZE',           'XSMALL',                     'SETTINGS', 'The initial warehouse size of the serverless Task that START_QUEUE creates.', 'Y')
  AS src (CODE, VALUE, "GROUP", DESCRIPTION, ACTIVE_INDICATOR)) AS src
ON tgt.CODE = src.CODE
WHEN MATCHED AND src.CODE IN ('DIRECT_VERSION', 'DIRECT_EDITION') THEN UPDATE SET VALUE = src.VALUE, DESCRIPTION = src.DESCRIPTION
WHEN NOT MATCHED THEN INSERT (CODE, VALUE, "GROUP", DESCRIPTION, ACTIVE_INDICATOR) VALUES (src.CODE, src.VALUE, src."GROUP", src.DESCRIPTION, src.ACTIVE_INDICATOR);

-- Placeholder rows for runs that are not connected to a Batch or Module.
MERGE INTO <% database %>.OMD.BATCH AS tgt
USING (SELECT 0 AS BATCH_ID, 'Default Batch' AS BATCH_CODE, 'Maintenance' AS BATCH_TYPE, 'On-demand' AS FREQUENCY_CODE, 'Y' AS ACTIVE_INDICATOR, 'Placeholder value for disconnected Batch runs' AS BATCH_DESCRIPTION) AS src
ON tgt.BATCH_ID = src.BATCH_ID
WHEN NOT MATCHED THEN INSERT (BATCH_ID, BATCH_CODE, BATCH_TYPE, FREQUENCY_CODE, ACTIVE_INDICATOR, BATCH_DESCRIPTION)
  VALUES (src.BATCH_ID, src.BATCH_CODE, src.BATCH_TYPE, src.FREQUENCY_CODE, src.ACTIVE_INDICATOR, src.BATCH_DESCRIPTION);

MERGE INTO <% database %>.OMD.BATCH_INSTANCE AS tgt
USING (SELECT 0 AS BATCH_INSTANCE_ID) AS src
ON tgt.BATCH_INSTANCE_ID = src.BATCH_INSTANCE_ID
WHEN NOT MATCHED THEN INSERT (BATCH_INSTANCE_ID, BATCH_ID, PARENT_BATCH_INSTANCE_ID, START_TIMESTAMP, END_TIMESTAMP, INTERNAL_PROCESSING_CODE, NEXT_RUN_STATUS_CODE, EXECUTION_STATUS_CODE, EXECUTION_CONTEXT)
  VALUES (0, 0, 0, '0001-01-01'::TIMESTAMP_NTZ, '9999-12-31'::TIMESTAMP_NTZ, 'Proceed', 'Proceed', 'Succeeded', '');

MERGE INTO <% database %>.OMD.MODULE AS tgt
USING (SELECT 0 AS MODULE_ID) AS src
ON tgt.MODULE_ID = src.MODULE_ID
WHEN NOT MATCHED THEN INSERT (MODULE_ID, MODULE_CODE, MODULE_TYPE, DATA_OBJECT_SOURCE, DATA_OBJECT_TARGET, AREA_CODE, FREQUENCY_CODE, ACTIVE_INDICATOR, MODULE_DESCRIPTION, EXECUTABLE)
  VALUES (0, 'Default Module', 'DataLogistics', 'N/A', 'N/A', 'MAINT', 'On-demand', 'Y', 'Placeholder value for disconnected Module runs', 'SELECT NULL');

MERGE INTO <% database %>.OMD.MODULE_INSTANCE_EXECUTED_CODE AS tgt
USING (SELECT REPEAT('0', 128) AS CHECKSUM) AS src
ON tgt.CHECKSUM = src.CHECKSUM
WHEN NOT MATCHED THEN INSERT (CHECKSUM, EXECUTED_CODE) VALUES (src.CHECKSUM, '');

MERGE INTO <% database %>.OMD.MODULE_INSTANCE AS tgt
USING (SELECT 0 AS MODULE_INSTANCE_ID) AS src
ON tgt.MODULE_INSTANCE_ID = src.MODULE_INSTANCE_ID
WHEN NOT MATCHED THEN INSERT (MODULE_INSTANCE_ID, MODULE_ID, BATCH_INSTANCE_ID, START_TIMESTAMP, END_TIMESTAMP, INTERNAL_PROCESSING_CODE, NEXT_RUN_STATUS_CODE, EXECUTION_STATUS_CODE, EXECUTION_CONTEXT, ROWS_INPUT, ROWS_INSERTED, ROWS_UPDATED, ROWS_DELETED, ROWS_DISCARDED, ROWS_REJECTED, EXECUTED_CODE_CHECKSUM)
  VALUES (0, 0, 0, '0001-01-01'::TIMESTAMP_NTZ, '9999-12-31'::TIMESTAMP_NTZ, 'Proceed', 'Proceed', 'Succeeded', 'N/A', 0, 0, 0, 0, 0, 0, REPEAT('0', 128));

-- >>> 04_Functions.sql
/*
 * DIRECT Framework - Snowflake edition
 * 04 Functions
 */

-- A setting value, or NULL when the setting does not exist or is inactive.
CREATE OR REPLACE FUNCTION <% database %>.OMD_METADATA.GET_SETTING(P_CODE VARCHAR)
RETURNS VARCHAR
AS
$$
    SELECT MAX(VALUE) FROM <% database %>.OMD_METADATA.FRAMEWORK_METADATA WHERE CODE = P_CODE AND ACTIVE_INDICATOR = 'Y'
$$;

-- A setting flag: 'Y' when the setting is Y (any case), otherwise 'N'.
CREATE OR REPLACE FUNCTION <% database %>.OMD_METADATA.GET_SETTING_FLAG(P_CODE VARCHAR)
RETURNS VARCHAR
AS
$$
    SELECT IFF(UPPER(COALESCE(MAX(VALUE), 'N')) = 'Y', 'Y', 'N') FROM <% database %>.OMD_METADATA.FRAMEWORK_METADATA WHERE CODE = P_CODE AND ACTIVE_INDICATOR = 'Y'
$$;

CREATE OR REPLACE FUNCTION <% database %>.OMD_METADATA.GET_FRAMEWORK_VERSION()
RETURNS VARCHAR
AS
$$
    SELECT COALESCE(<% database %>.OMD_METADATA.GET_SETTING('DIRECT_VERSION'), 'Unknown') || ' (' || COALESCE(<% database %>.OMD_METADATA.GET_SETTING('DIRECT_EDITION'), 'Unknown') || ')'
$$;

-- A timestamp as text, in the configured format (UTC).
CREATE OR REPLACE FUNCTION <% database %>.OMD_METADATA.GET_TIMESTAMP_STRING(P_TIMESTAMP TIMESTAMP_NTZ)
RETURNS VARCHAR
AS
$$
    SELECT TO_VARCHAR(P_TIMESTAMP, COALESCE(<% database %>.OMD_METADATA.GET_SETTING('TIMESTAMP_FORMAT'), 'YYYY-MM-DD HH24:MI:SS.FF7'))
$$;

CREATE OR REPLACE FUNCTION <% database %>.OMD.GET_BATCH_ID_BY_CODE(P_BATCH_CODE VARCHAR)
RETURNS NUMBER
AS
$$
    SELECT MAX(BATCH_ID) FROM <% database %>.OMD.BATCH WHERE BATCH_CODE = P_BATCH_CODE
$$;

CREATE OR REPLACE FUNCTION <% database %>.OMD.GET_MODULE_ID_BY_CODE(P_MODULE_CODE VARCHAR)
RETURNS NUMBER
AS
$$
    SELECT MAX(MODULE_ID) FROM <% database %>.OMD.MODULE WHERE MODULE_CODE = P_MODULE_CODE
$$;

CREATE OR REPLACE FUNCTION <% database %>.OMD.GET_BATCH_CODE_BY_ID(P_BATCH_ID NUMBER)
RETURNS VARCHAR
AS
$$
    SELECT MAX(BATCH_CODE) FROM <% database %>.OMD.BATCH WHERE BATCH_ID = P_BATCH_ID
$$;

CREATE OR REPLACE FUNCTION <% database %>.OMD.GET_MODULE_ID_BY_MODULE_INSTANCE_ID(P_MODULE_INSTANCE_ID NUMBER)
RETURNS NUMBER
AS
$$
    SELECT MAX(MODULE_ID) FROM <% database %>.OMD.MODULE_INSTANCE WHERE MODULE_INSTANCE_ID = P_MODULE_INSTANCE_ID
$$;

CREATE OR REPLACE FUNCTION <% database %>.OMD.GET_BATCH_ID_BY_BATCH_INSTANCE_ID(P_BATCH_INSTANCE_ID NUMBER)
RETURNS NUMBER
AS
$$
    SELECT MAX(BATCH_ID) FROM <% database %>.OMD.BATCH_INSTANCE WHERE BATCH_INSTANCE_ID = P_BATCH_INSTANCE_ID
$$;

-- The Batch Id a Module Instance ran under (0 when it ran stand-alone).
CREATE OR REPLACE FUNCTION <% database %>.OMD.GET_BATCH_ID_BY_MODULE_INSTANCE_ID(P_MODULE_INSTANCE_ID NUMBER)
RETURNS NUMBER
AS
$$
    SELECT COALESCE(MAX(bi.BATCH_ID), 0)
    FROM <% database %>.OMD.MODULE_INSTANCE mi
    JOIN <% database %>.OMD.BATCH_INSTANCE bi ON mi.BATCH_INSTANCE_ID = bi.BATCH_INSTANCE_ID
    WHERE mi.MODULE_INSTANCE_ID = P_MODULE_INSTANCE_ID
$$;

-- The active indicator of a Batch/Module relationship: 'Y', 'N', or 'U' when the relationship does not exist.
CREATE OR REPLACE FUNCTION <% database %>.OMD.GET_BATCH_MODULE_ACTIVE_INDICATOR_VALUE(P_BATCH_ID NUMBER, P_MODULE_ID NUMBER)
RETURNS VARCHAR
AS
$$
    SELECT COALESCE(MAX(ACTIVE_INDICATOR), 'U') FROM <% database %>.OMD.BATCH_MODULE WHERE BATCH_ID = P_BATCH_ID AND MODULE_ID = P_MODULE_ID
$$;

-- The most recent load window value of a Module: 1 = start value, 2 = end value.
CREATE OR REPLACE FUNCTION <% database %>.OMD.GET_MODULE_LOAD_WINDOW_VALUE(P_MODULE_ID NUMBER, P_START_OR_END NUMBER)
RETURNS VARCHAR
AS
$$
    SELECT MAX_BY(IFF(P_START_OR_END = 1, START_VALUE, END_VALUE), SOURCE_CONTROL_ID)
    FROM <% database %>.OMD.SOURCE_CONTROL
    WHERE MODULE_ID = P_MODULE_ID
$$;

-- >>> 05_Procedures_Registration.sql
/*
 * DIRECT Framework - Snowflake edition
 * 05 Registration procedures
 *
 * REGISTER_BATCH, REGISTER_MODULE, ADD_MODULE_TO_BATCH and
 * ADD_BATCH_TO_PARENT_BATCH register the metadata that a run needs. They can be
 * run again: an existing Batch or Module is updated when its attributes changed
 * (the active indicator is left alone, so it can be managed separately), and an
 * existing relationship keeps its active indicator.
 */

CREATE OR REPLACE PROCEDURE <% database %>.OMD.REGISTER_BATCH
(
    P_BATCH_CODE         VARCHAR,
    P_BATCH_TYPE         VARCHAR DEFAULT 'Batch',
    P_FREQUENCY_CODE     VARCHAR DEFAULT 'On-demand',
    P_BATCH_DESCRIPTION  VARCHAR DEFAULT '',
    P_ACTIVE_INDICATOR   VARCHAR DEFAULT 'Y'
)
RETURNS NUMBER
LANGUAGE SQL
COMMENT = 'Registers a Batch, or updates its attributes when it exists. Returns the Batch Id.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_BATCH_ID NUMBER;
BEGIN
    IF (P_BATCH_CODE IS NULL OR TRIM(P_BATCH_CODE) = '') THEN
        RETURN NULL;
    END IF;

    SELECT MAX(BATCH_ID) INTO :V_BATCH_ID FROM <% database %>.OMD.BATCH WHERE BATCH_CODE = :P_BATCH_CODE;

    IF (V_BATCH_ID IS NULL) THEN
        SELECT <% database %>.OMD.BATCH_SEQ.NEXTVAL INTO :V_BATCH_ID;
        INSERT INTO <% database %>.OMD.BATCH (BATCH_ID, BATCH_CODE, BATCH_TYPE, FREQUENCY_CODE, ACTIVE_INDICATOR, BATCH_DESCRIPTION)
        VALUES (:V_BATCH_ID, :P_BATCH_CODE, :P_BATCH_TYPE, COALESCE(:P_FREQUENCY_CODE, 'On-demand'), COALESCE(:P_ACTIVE_INDICATOR, 'Y'), :P_BATCH_DESCRIPTION);
    ELSE
        UPDATE <% database %>.OMD.BATCH
        SET BATCH_TYPE = :P_BATCH_TYPE,
            FREQUENCY_CODE = COALESCE(:P_FREQUENCY_CODE, 'On-demand'),
            BATCH_DESCRIPTION = :P_BATCH_DESCRIPTION
        WHERE BATCH_ID = :V_BATCH_ID
          AND (COALESCE(BATCH_TYPE, '') <> COALESCE(:P_BATCH_TYPE, '')
            OR FREQUENCY_CODE <> COALESCE(:P_FREQUENCY_CODE, 'On-demand')
            OR COALESCE(BATCH_DESCRIPTION, '') <> COALESCE(:P_BATCH_DESCRIPTION, ''));
    END IF;

    RETURN V_BATCH_ID;
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.REGISTER_MODULE
(
    P_MODULE_CODE         VARCHAR,
    P_EXECUTABLE          VARCHAR DEFAULT 'SELECT NULL',
    P_AREA_CODE           VARCHAR DEFAULT 'MAINT',
    P_DATA_OBJECT_SOURCE  VARCHAR DEFAULT 'N/A',
    P_DATA_OBJECT_TARGET  VARCHAR DEFAULT 'N/A',
    P_MODULE_DESCRIPTION  VARCHAR DEFAULT '',
    P_MODULE_TYPE         VARCHAR DEFAULT 'DataLogistics',
    P_FREQUENCY_CODE      VARCHAR DEFAULT 'On-demand',
    P_ACTIVE_INDICATOR    VARCHAR DEFAULT 'Y'
)
RETURNS NUMBER
LANGUAGE SQL
COMMENT = 'Registers a Module, or updates its attributes when it exists. Returns the Module Id. The executable may use the tokens :ModuleInstanceId, :StartValue, :EndValue and :ConsistencyDateTime.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_MODULE_ID NUMBER;
BEGIN
    IF (P_MODULE_CODE IS NULL OR TRIM(P_MODULE_CODE) = '') THEN
        RETURN NULL;
    END IF;

    SELECT MAX(MODULE_ID) INTO :V_MODULE_ID FROM <% database %>.OMD.MODULE WHERE MODULE_CODE = :P_MODULE_CODE;

    IF (V_MODULE_ID IS NULL) THEN
        SELECT <% database %>.OMD.MODULE_SEQ.NEXTVAL INTO :V_MODULE_ID;
        INSERT INTO <% database %>.OMD.MODULE (MODULE_ID, MODULE_CODE, MODULE_TYPE, DATA_OBJECT_SOURCE, DATA_OBJECT_TARGET, AREA_CODE, FREQUENCY_CODE, ACTIVE_INDICATOR, MODULE_DESCRIPTION, EXECUTABLE)
        VALUES (:V_MODULE_ID, :P_MODULE_CODE, COALESCE(:P_MODULE_TYPE, 'DataLogistics'), COALESCE(:P_DATA_OBJECT_SOURCE, 'N/A'), COALESCE(:P_DATA_OBJECT_TARGET, 'N/A'),
                COALESCE(:P_AREA_CODE, 'MAINT'), COALESCE(:P_FREQUENCY_CODE, 'On-demand'), COALESCE(:P_ACTIVE_INDICATOR, 'Y'), :P_MODULE_DESCRIPTION, :P_EXECUTABLE);
    ELSE
        UPDATE <% database %>.OMD.MODULE
        SET MODULE_TYPE = COALESCE(:P_MODULE_TYPE, 'DataLogistics'),
            DATA_OBJECT_SOURCE = COALESCE(:P_DATA_OBJECT_SOURCE, 'N/A'),
            DATA_OBJECT_TARGET = COALESCE(:P_DATA_OBJECT_TARGET, 'N/A'),
            AREA_CODE = COALESCE(:P_AREA_CODE, 'MAINT'),
            FREQUENCY_CODE = COALESCE(:P_FREQUENCY_CODE, 'On-demand'),
            MODULE_DESCRIPTION = :P_MODULE_DESCRIPTION,
            EXECUTABLE = :P_EXECUTABLE
        WHERE MODULE_ID = :V_MODULE_ID
          AND (MODULE_TYPE <> COALESCE(:P_MODULE_TYPE, 'DataLogistics')
            OR DATA_OBJECT_SOURCE <> COALESCE(:P_DATA_OBJECT_SOURCE, 'N/A')
            OR DATA_OBJECT_TARGET <> COALESCE(:P_DATA_OBJECT_TARGET, 'N/A')
            OR AREA_CODE <> COALESCE(:P_AREA_CODE, 'MAINT')
            OR FREQUENCY_CODE <> COALESCE(:P_FREQUENCY_CODE, 'On-demand')
            OR COALESCE(MODULE_DESCRIPTION, '') <> COALESCE(:P_MODULE_DESCRIPTION, '')
            OR COALESCE(EXECUTABLE, '') <> COALESCE(:P_EXECUTABLE, ''));
    END IF;

    RETURN V_MODULE_ID;
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.ADD_MODULE_TO_BATCH
(
    P_MODULE_CODE       VARCHAR,
    P_BATCH_CODE        VARCHAR,
    P_SEQUENCE          NUMBER DEFAULT NULL,
    P_ACTIVE_INDICATOR  VARCHAR DEFAULT 'Y'
)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT = 'Adds a Module to a Batch at the given position (default: after the last Module). An existing relationship gets the new position when one is given.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_MODULE_ID NUMBER;
    V_BATCH_ID NUMBER;
    V_SEQUENCE NUMBER;
    V_EXISTS NUMBER;
BEGIN
    V_MODULE_ID := <% database %>.OMD.GET_MODULE_ID_BY_CODE(P_MODULE_CODE);
    V_BATCH_ID := <% database %>.OMD.GET_BATCH_ID_BY_CODE(P_BATCH_CODE);

    IF (V_MODULE_ID IS NULL) THEN
        RETURN 'The Module ''' || COALESCE(P_MODULE_CODE, '') || ''' is not registered.';
    END IF;
    IF (V_BATCH_ID IS NULL) THEN
        RETURN 'The Batch ''' || COALESCE(P_BATCH_CODE, '') || ''' is not registered.';
    END IF;

    SELECT COUNT(*) INTO :V_EXISTS FROM <% database %>.OMD.BATCH_MODULE WHERE BATCH_ID = :V_BATCH_ID AND MODULE_ID = :V_MODULE_ID;

    IF (V_EXISTS > 0) THEN
        IF (P_SEQUENCE IS NOT NULL) THEN
            UPDATE <% database %>.OMD.BATCH_MODULE SET SEQUENCE = :P_SEQUENCE WHERE BATCH_ID = :V_BATCH_ID AND MODULE_ID = :V_MODULE_ID AND SEQUENCE <> :P_SEQUENCE;
        END IF;
        RETURN 'The Module ''' || P_MODULE_CODE || ''' is already part of Batch ''' || P_BATCH_CODE || '''.';
    END IF;

    IF (P_SEQUENCE IS NULL) THEN
        SELECT COALESCE(MAX(SEQUENCE), 0) + 1 INTO :V_SEQUENCE FROM <% database %>.OMD.BATCH_MODULE WHERE BATCH_ID = :V_BATCH_ID;
    ELSE
        V_SEQUENCE := P_SEQUENCE;
    END IF;

    INSERT INTO <% database %>.OMD.BATCH_MODULE (BATCH_ID, MODULE_ID, SEQUENCE, ACTIVE_INDICATOR)
    VALUES (:V_BATCH_ID, :V_MODULE_ID, :V_SEQUENCE, COALESCE(:P_ACTIVE_INDICATOR, 'Y'));

    RETURN 'The Module ''' || P_MODULE_CODE || ''' was added to Batch ''' || P_BATCH_CODE || ''' at position ' || TO_VARCHAR(V_SEQUENCE) || '.';
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.ADD_BATCH_TO_PARENT_BATCH
(
    P_BATCH_CODE         VARCHAR,
    P_PARENT_BATCH_CODE  VARCHAR,
    P_SEQUENCE           NUMBER DEFAULT NULL,
    P_ACTIVE_INDICATOR   VARCHAR DEFAULT 'Y'
)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT = 'Adds a Batch as child of a parent Batch at the given position (default: after the last child). A relationship that would create a cycle is refused.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_BATCH_ID NUMBER;
    V_PARENT_BATCH_ID NUMBER;
    V_SEQUENCE NUMBER;
    V_EXISTS NUMBER;
    V_CYCLE NUMBER;
BEGIN
    V_BATCH_ID := <% database %>.OMD.GET_BATCH_ID_BY_CODE(P_BATCH_CODE);
    V_PARENT_BATCH_ID := <% database %>.OMD.GET_BATCH_ID_BY_CODE(P_PARENT_BATCH_CODE);

    IF (V_BATCH_ID IS NULL) THEN
        RETURN 'The Batch ''' || COALESCE(P_BATCH_CODE, '') || ''' is not registered.';
    END IF;
    IF (V_PARENT_BATCH_ID IS NULL) THEN
        RETURN 'The parent Batch ''' || COALESCE(P_PARENT_BATCH_CODE, '') || ''' is not registered.';
    END IF;
    IF (V_BATCH_ID = V_PARENT_BATCH_ID) THEN
        RETURN 'A Batch cannot be its own parent.';
    END IF;

    -- The parent, or any of its ancestors, must not be the child: that would be a cycle.
    SELECT COUNT(*) INTO :V_CYCLE
    FROM
    (
        WITH RECURSIVE ANCESTORS AS
        (
            SELECT PARENT_BATCH_ID, BATCH_ID FROM <% database %>.OMD.BATCH_HIERARCHY WHERE BATCH_ID = :V_PARENT_BATCH_ID
            UNION ALL
            SELECT bh.PARENT_BATCH_ID, bh.BATCH_ID
            FROM <% database %>.OMD.BATCH_HIERARCHY bh
            JOIN ANCESTORS a ON bh.BATCH_ID = a.PARENT_BATCH_ID
        )
        SELECT PARENT_BATCH_ID FROM ANCESTORS WHERE PARENT_BATCH_ID = :V_BATCH_ID
    ) cycles;

    IF (V_CYCLE > 0) THEN
        RETURN 'Adding Batch ''' || P_BATCH_CODE || ''' under ''' || P_PARENT_BATCH_CODE || ''' would create a cycle.';
    END IF;

    SELECT COUNT(*) INTO :V_EXISTS FROM <% database %>.OMD.BATCH_HIERARCHY WHERE PARENT_BATCH_ID = :V_PARENT_BATCH_ID AND BATCH_ID = :V_BATCH_ID;

    IF (V_EXISTS > 0) THEN
        IF (P_SEQUENCE IS NOT NULL) THEN
            UPDATE <% database %>.OMD.BATCH_HIERARCHY SET SEQUENCE = :P_SEQUENCE WHERE PARENT_BATCH_ID = :V_PARENT_BATCH_ID AND BATCH_ID = :V_BATCH_ID AND SEQUENCE <> :P_SEQUENCE;
        END IF;
        RETURN 'The Batch ''' || P_BATCH_CODE || ''' is already a child of ''' || P_PARENT_BATCH_CODE || '''.';
    END IF;

    IF (P_SEQUENCE IS NULL) THEN
        SELECT COALESCE(MAX(SEQUENCE), 0) + 1 INTO :V_SEQUENCE FROM <% database %>.OMD.BATCH_HIERARCHY WHERE PARENT_BATCH_ID = :V_PARENT_BATCH_ID;
    ELSE
        V_SEQUENCE := P_SEQUENCE;
    END IF;

    INSERT INTO <% database %>.OMD.BATCH_HIERARCHY (PARENT_BATCH_ID, BATCH_ID, SEQUENCE, ACTIVE_INDICATOR)
    VALUES (:V_PARENT_BATCH_ID, :V_BATCH_ID, :V_SEQUENCE, COALESCE(:P_ACTIVE_INDICATOR, 'Y'));

    RETURN 'The Batch ''' || P_BATCH_CODE || ''' was added to ''' || P_PARENT_BATCH_CODE || ''' at position ' || TO_VARCHAR(V_SEQUENCE) || '.';
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.SET_SETTING
(
    P_CODE   VARCHAR,
    P_VALUE  VARCHAR
)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT = 'Sets the value of a framework setting in OMD_METADATA.FRAMEWORK_METADATA. The setting must exist.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_EXISTS NUMBER;
BEGIN
    SELECT COUNT(*) INTO :V_EXISTS FROM <% database %>.OMD_METADATA.FRAMEWORK_METADATA WHERE CODE = :P_CODE;
    IF (V_EXISTS = 0) THEN
        RETURN 'The setting ''' || COALESCE(P_CODE, '') || ''' does not exist.';
    END IF;
    UPDATE <% database %>.OMD_METADATA.FRAMEWORK_METADATA SET VALUE = :P_VALUE WHERE CODE = :P_CODE;
    RETURN 'The setting ''' || P_CODE || ''' is now ''' || COALESCE(P_VALUE, '') || '''.';
END;
$$;

-- >>> 06_Procedures_Instances.sql
/*
 * DIRECT Framework - Snowflake edition
 * 06 Instance procedures
 *
 * Event log, creation and status updates of Batch Instances and Module
 * Instances, and the load window administration (SOURCE_CONTROL).
 */

CREATE OR REPLACE PROCEDURE <% database %>.OMD.INSERT_INTO_EVENT_LOG
(
    P_EVENT_DETAIL        VARCHAR,
    P_MODULE_INSTANCE_ID  NUMBER DEFAULT 0,
    P_BATCH_INSTANCE_ID   NUMBER DEFAULT 0,
    P_EVENT_TYPE_CODE     NUMBER DEFAULT 2,
    P_EVENT_RETURN_CODE   VARCHAR DEFAULT NULL,
    P_ERROR_BITMAP        NUMBER DEFAULT NULL
)
RETURNS NUMBER
LANGUAGE SQL
COMMENT = 'Writes an event to OMD.EVENT_LOG. The Batch Instance Id is derived from the Module Instance when it is not given. Returns the Event Id.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_EVENT_ID NUMBER;
    V_BATCH_INSTANCE_ID NUMBER;
BEGIN
    V_BATCH_INSTANCE_ID := COALESCE(P_BATCH_INSTANCE_ID, 0);
    IF (V_BATCH_INSTANCE_ID = 0 AND COALESCE(P_MODULE_INSTANCE_ID, 0) <> 0) THEN
        SELECT COALESCE(MAX(BATCH_INSTANCE_ID), 0) INTO :V_BATCH_INSTANCE_ID FROM <% database %>.OMD.MODULE_INSTANCE WHERE MODULE_INSTANCE_ID = :P_MODULE_INSTANCE_ID;
    END IF;

    SELECT <% database %>.OMD.EVENT_LOG_SEQ.NEXTVAL INTO :V_EVENT_ID;

    INSERT INTO <% database %>.OMD.EVENT_LOG (EVENT_ID, BATCH_INSTANCE_ID, MODULE_INSTANCE_ID, EVENT_TYPE_CODE, EVENT_TIMESTAMP, EVENT_RETURN_CODE, EVENT_DETAIL, ERROR_BITMAP)
    VALUES (:V_EVENT_ID, :V_BATCH_INSTANCE_ID, COALESCE(:P_MODULE_INSTANCE_ID, 0), COALESCE(:P_EVENT_TYPE_CODE, 2), SYSDATE(), :P_EVENT_RETURN_CODE, LEFT(:P_EVENT_DETAIL, 4000), :P_ERROR_BITMAP);

    RETURN V_EVENT_ID;
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.UPDATE_MODULE_INSTANCE
(
    P_MODULE_INSTANCE_ID  NUMBER,
    P_EVENT_CODE          VARCHAR,
    P_ROWS_INPUT          NUMBER DEFAULT 0,
    P_ROWS_INSERTED       NUMBER DEFAULT 0,
    P_ROWS_UPDATED        NUMBER DEFAULT 0,
    P_ROWS_DELETED        NUMBER DEFAULT 0,
    P_ROWS_DISCARDED      NUMBER DEFAULT 0,
    P_ROWS_REJECTED       NUMBER DEFAULT 0
)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT = 'Applies an event (Proceed, Cancel, Abort, Rollback, Success, Failure) to a Module Instance and sets its status columns accordingly.'
EXECUTE AS OWNER
AS
$$
BEGIN
    CASE (P_EVENT_CODE)
        WHEN 'Proceed' THEN
            UPDATE <% database %>.OMD.MODULE_INSTANCE SET INTERNAL_PROCESSING_CODE = 'Proceed' WHERE MODULE_INSTANCE_ID = :P_MODULE_INSTANCE_ID;
        WHEN 'Rollback' THEN
            UPDATE <% database %>.OMD.MODULE_INSTANCE SET INTERNAL_PROCESSING_CODE = 'Rollback' WHERE MODULE_INSTANCE_ID = :P_MODULE_INSTANCE_ID;
        WHEN 'Cancel' THEN
            UPDATE <% database %>.OMD.MODULE_INSTANCE SET INTERNAL_PROCESSING_CODE = 'Cancel', NEXT_RUN_STATUS_CODE = 'Proceed', EXECUTION_STATUS_CODE = 'Cancelled', END_TIMESTAMP = SYSDATE() WHERE MODULE_INSTANCE_ID = :P_MODULE_INSTANCE_ID;
        WHEN 'Abort' THEN
            UPDATE <% database %>.OMD.MODULE_INSTANCE SET INTERNAL_PROCESSING_CODE = 'Abort', NEXT_RUN_STATUS_CODE = 'Proceed', EXECUTION_STATUS_CODE = 'Aborted', END_TIMESTAMP = SYSDATE() WHERE MODULE_INSTANCE_ID = :P_MODULE_INSTANCE_ID;
        WHEN 'Success' THEN
            UPDATE <% database %>.OMD.MODULE_INSTANCE
            SET NEXT_RUN_STATUS_CODE = 'Proceed', EXECUTION_STATUS_CODE = 'Succeeded', END_TIMESTAMP = SYSDATE(),
                ROWS_INPUT = :P_ROWS_INPUT, ROWS_INSERTED = :P_ROWS_INSERTED, ROWS_UPDATED = :P_ROWS_UPDATED, ROWS_DELETED = :P_ROWS_DELETED, ROWS_DISCARDED = :P_ROWS_DISCARDED, ROWS_REJECTED = :P_ROWS_REJECTED
            WHERE MODULE_INSTANCE_ID = :P_MODULE_INSTANCE_ID;
        WHEN 'Failure' THEN
            UPDATE <% database %>.OMD.MODULE_INSTANCE
            SET NEXT_RUN_STATUS_CODE = 'Rollback', EXECUTION_STATUS_CODE = 'Failed', END_TIMESTAMP = SYSDATE(),
                ROWS_INPUT = :P_ROWS_INPUT, ROWS_INSERTED = :P_ROWS_INSERTED, ROWS_UPDATED = :P_ROWS_UPDATED, ROWS_DELETED = :P_ROWS_DELETED, ROWS_DISCARDED = :P_ROWS_DISCARDED, ROWS_REJECTED = :P_ROWS_REJECTED
            WHERE MODULE_INSTANCE_ID = :P_MODULE_INSTANCE_ID;
        ELSE
            RETURN 'Unknown event code ''' || COALESCE(P_EVENT_CODE, '') || '''.';
    END CASE;
    RETURN 'Module Instance ' || TO_VARCHAR(P_MODULE_INSTANCE_ID) || ' received event ''' || P_EVENT_CODE || '''.';
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.UPDATE_BATCH_INSTANCE
(
    P_BATCH_INSTANCE_ID  NUMBER,
    P_EVENT_CODE         VARCHAR
)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT = 'Applies an event (Proceed, Cancel, Abort, Rollback, Success, Failure) to a Batch Instance and sets its status columns accordingly.'
EXECUTE AS OWNER
AS
$$
BEGIN
    CASE (P_EVENT_CODE)
        WHEN 'Proceed' THEN
            UPDATE <% database %>.OMD.BATCH_INSTANCE SET INTERNAL_PROCESSING_CODE = 'Proceed' WHERE BATCH_INSTANCE_ID = :P_BATCH_INSTANCE_ID;
        WHEN 'Rollback' THEN
            UPDATE <% database %>.OMD.BATCH_INSTANCE SET INTERNAL_PROCESSING_CODE = 'Rollback' WHERE BATCH_INSTANCE_ID = :P_BATCH_INSTANCE_ID;
        WHEN 'Cancel' THEN
            UPDATE <% database %>.OMD.BATCH_INSTANCE SET INTERNAL_PROCESSING_CODE = 'Cancel', NEXT_RUN_STATUS_CODE = 'Proceed', EXECUTION_STATUS_CODE = 'Cancelled', END_TIMESTAMP = SYSDATE() WHERE BATCH_INSTANCE_ID = :P_BATCH_INSTANCE_ID;
        WHEN 'Abort' THEN
            UPDATE <% database %>.OMD.BATCH_INSTANCE SET INTERNAL_PROCESSING_CODE = 'Abort', NEXT_RUN_STATUS_CODE = 'Proceed', EXECUTION_STATUS_CODE = 'Aborted', END_TIMESTAMP = SYSDATE() WHERE BATCH_INSTANCE_ID = :P_BATCH_INSTANCE_ID;
        WHEN 'Success' THEN
            UPDATE <% database %>.OMD.BATCH_INSTANCE SET NEXT_RUN_STATUS_CODE = 'Proceed', EXECUTION_STATUS_CODE = 'Succeeded', END_TIMESTAMP = SYSDATE() WHERE BATCH_INSTANCE_ID = :P_BATCH_INSTANCE_ID;
        WHEN 'Failure' THEN
            -- A failed Batch keeps 'Proceed' as next run status: the next run skips the Modules that succeeded and rolls back the ones that failed.
            UPDATE <% database %>.OMD.BATCH_INSTANCE SET NEXT_RUN_STATUS_CODE = 'Proceed', EXECUTION_STATUS_CODE = 'Failed', END_TIMESTAMP = SYSDATE() WHERE BATCH_INSTANCE_ID = :P_BATCH_INSTANCE_ID;
        ELSE
            RETURN 'Unknown event code ''' || COALESCE(P_EVENT_CODE, '') || '''.';
    END CASE;
    RETURN 'Batch Instance ' || TO_VARCHAR(P_BATCH_INSTANCE_ID) || ' received event ''' || P_EVENT_CODE || '''.';
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.CREATE_BATCH_INSTANCE
(
    P_BATCH_CODE               VARCHAR,
    P_PARENT_BATCH_INSTANCE_ID NUMBER DEFAULT 0,
    P_EXECUTION_CONTEXT        VARCHAR DEFAULT ''
)
RETURNS NUMBER
LANGUAGE SQL
COMMENT = 'Creates a Batch Instance in the Executing state and returns its Id. Registers the Batch and the parent relationship when the settings allow it.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_BATCH_ID NUMBER;
    V_PARENT_BATCH_ID NUMBER;
    V_BATCH_INSTANCE_ID NUMBER;
    V_EXISTS NUMBER;
    V_MESSAGE VARCHAR;
BEGIN
    V_BATCH_ID := <% database %>.OMD.GET_BATCH_ID_BY_CODE(P_BATCH_CODE);

    IF (V_BATCH_ID IS NULL) THEN
        IF (<% database %>.OMD_METADATA.GET_SETTING_FLAG('AUTO_REGISTER_BATCHES') = 'Y') THEN
            CALL <% database %>.OMD.REGISTER_BATCH(:P_BATCH_CODE) INTO :V_BATCH_ID;
        END IF;
        IF (V_BATCH_ID IS NULL) THEN
            V_MESSAGE := 'The Batch ''' || COALESCE(P_BATCH_CODE, '') || ''' is not registered and automatic registration is off.';
            CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE);
            RETURN NULL;
        END IF;
    END IF;

    -- A child Batch must be registered under its parent.
    IF (COALESCE(P_PARENT_BATCH_INSTANCE_ID, 0) <> 0) THEN
        V_PARENT_BATCH_ID := <% database %>.OMD.GET_BATCH_ID_BY_BATCH_INSTANCE_ID(P_PARENT_BATCH_INSTANCE_ID);
        IF (V_PARENT_BATCH_ID IS NOT NULL AND V_PARENT_BATCH_ID <> V_BATCH_ID) THEN
            SELECT COUNT(*) INTO :V_EXISTS FROM <% database %>.OMD.BATCH_HIERARCHY WHERE PARENT_BATCH_ID = :V_PARENT_BATCH_ID AND BATCH_ID = :V_BATCH_ID;
            IF (V_EXISTS = 0 AND <% database %>.OMD_METADATA.GET_SETTING_FLAG('AUTO_REGISTER_RELATIONSHIPS') = 'Y') THEN
                CALL <% database %>.OMD.ADD_BATCH_TO_PARENT_BATCH(:P_BATCH_CODE, <% database %>.OMD.GET_BATCH_CODE_BY_ID(:V_PARENT_BATCH_ID));
            END IF;
        END IF;
    END IF;

    SELECT <% database %>.OMD.BATCH_INSTANCE_SEQ.NEXTVAL INTO :V_BATCH_INSTANCE_ID;

    INSERT INTO <% database %>.OMD.BATCH_INSTANCE (BATCH_INSTANCE_ID, BATCH_ID, PARENT_BATCH_INSTANCE_ID, START_TIMESTAMP, END_TIMESTAMP, INTERNAL_PROCESSING_CODE, NEXT_RUN_STATUS_CODE, EXECUTION_STATUS_CODE, EXECUTION_CONTEXT)
    VALUES (:V_BATCH_INSTANCE_ID, :V_BATCH_ID, COALESCE(:P_PARENT_BATCH_INSTANCE_ID, 0), SYSDATE(), NULL, 'Abort', 'Proceed', 'Executing', LEFT(COALESCE(:P_EXECUTION_CONTEXT, ''), 4000));

    RETURN V_BATCH_INSTANCE_ID;
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.CREATE_MODULE_INSTANCE
(
    P_MODULE_CODE        VARCHAR,
    P_BATCH_INSTANCE_ID  NUMBER DEFAULT 0,
    P_EXECUTION_CONTEXT  VARCHAR DEFAULT '',
    P_QUERY              VARCHAR DEFAULT NULL
)
RETURNS NUMBER
LANGUAGE SQL
COMMENT = 'Creates a Module Instance in the Executing state and returns its Id. The executed code (the query, or the registered executable) is stored by checksum. Registers the Module and the Batch/Module relationship when the settings allow it.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_MODULE_ID NUMBER;
    V_BATCH_ID NUMBER;
    V_MODULE_INSTANCE_ID NUMBER;
    V_EXECUTED_CODE VARCHAR;
    V_CHECKSUM VARCHAR;
    V_EXISTS NUMBER;
    V_MESSAGE VARCHAR;
BEGIN
    V_MODULE_ID := <% database %>.OMD.GET_MODULE_ID_BY_CODE(P_MODULE_CODE);

    IF (V_MODULE_ID IS NULL) THEN
        IF (<% database %>.OMD_METADATA.GET_SETTING_FLAG('AUTO_REGISTER_MODULES') = 'Y') THEN
            CALL <% database %>.OMD.REGISTER_MODULE(:P_MODULE_CODE, COALESCE(:P_QUERY, 'SELECT NULL')) INTO :V_MODULE_ID;
        END IF;
        IF (V_MODULE_ID IS NULL) THEN
            V_MESSAGE := 'The Module ''' || COALESCE(P_MODULE_CODE, '') || ''' is not registered and automatic registration is off.';
            CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, 0, :P_BATCH_INSTANCE_ID);
            RETURN NULL;
        END IF;
    END IF;

    -- A Module that runs from a Batch must be registered for that Batch.
    IF (COALESCE(P_BATCH_INSTANCE_ID, 0) <> 0) THEN
        V_BATCH_ID := <% database %>.OMD.GET_BATCH_ID_BY_BATCH_INSTANCE_ID(P_BATCH_INSTANCE_ID);
        IF (V_BATCH_ID IS NOT NULL) THEN
            SELECT COUNT(*) INTO :V_EXISTS FROM <% database %>.OMD.BATCH_MODULE WHERE BATCH_ID = :V_BATCH_ID AND MODULE_ID = :V_MODULE_ID;
            IF (V_EXISTS = 0 AND <% database %>.OMD_METADATA.GET_SETTING_FLAG('AUTO_REGISTER_RELATIONSHIPS') = 'Y') THEN
                CALL <% database %>.OMD.ADD_MODULE_TO_BATCH(:P_MODULE_CODE, <% database %>.OMD.GET_BATCH_CODE_BY_ID(:V_BATCH_ID));
            END IF;
        END IF;
    END IF;

    -- The executed code, stored once per distinct text.
    IF (P_QUERY IS NULL) THEN
        SELECT MAX(EXECUTABLE) INTO :V_EXECUTED_CODE FROM <% database %>.OMD.MODULE WHERE MODULE_ID = :V_MODULE_ID;
    ELSE
        V_EXECUTED_CODE := P_QUERY;
    END IF;

    IF (V_EXECUTED_CODE IS NULL OR V_EXECUTED_CODE = '') THEN
        V_CHECKSUM := REPEAT('0', 128);
    ELSE
        V_CHECKSUM := SHA2(V_EXECUTED_CODE, 512);
        SELECT COUNT(*) INTO :V_EXISTS FROM <% database %>.OMD.MODULE_INSTANCE_EXECUTED_CODE WHERE CHECKSUM = :V_CHECKSUM;
        IF (V_EXISTS = 0) THEN
            INSERT INTO <% database %>.OMD.MODULE_INSTANCE_EXECUTED_CODE (CHECKSUM, EXECUTED_CODE) VALUES (:V_CHECKSUM, :V_EXECUTED_CODE);
        END IF;
    END IF;

    SELECT <% database %>.OMD.MODULE_INSTANCE_SEQ.NEXTVAL INTO :V_MODULE_INSTANCE_ID;

    INSERT INTO <% database %>.OMD.MODULE_INSTANCE (MODULE_INSTANCE_ID, MODULE_ID, BATCH_INSTANCE_ID, START_TIMESTAMP, END_TIMESTAMP, INTERNAL_PROCESSING_CODE, NEXT_RUN_STATUS_CODE, EXECUTION_STATUS_CODE, EXECUTION_CONTEXT, EXECUTED_CODE_CHECKSUM)
    VALUES (:V_MODULE_INSTANCE_ID, :V_MODULE_ID, COALESCE(:P_BATCH_INSTANCE_ID, 0), SYSDATE(), NULL, 'Abort', 'Proceed', 'Executing', LEFT(COALESCE(:P_EXECUTION_CONTEXT, ''), 4000), :V_CHECKSUM);

    RETURN V_MODULE_INSTANCE_ID;
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.SET_SOURCE_CONTROL_VALUES
(
    P_MODULE_INSTANCE_ID  NUMBER,
    P_START_VALUE         VARCHAR,
    P_END_VALUE           VARCHAR
)
RETURNS NUMBER
LANGUAGE SQL
COMMENT = 'Records the load window of a Module Instance in OMD.SOURCE_CONTROL. Returns the Source Control Id.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_MODULE_ID NUMBER;
    V_SOURCE_CONTROL_ID NUMBER;
BEGIN
    V_MODULE_ID := <% database %>.OMD.GET_MODULE_ID_BY_MODULE_INSTANCE_ID(P_MODULE_INSTANCE_ID);
    IF (V_MODULE_ID IS NULL OR P_START_VALUE IS NULL) THEN
        RETURN NULL;
    END IF;

    SELECT <% database %>.OMD.SOURCE_CONTROL_SEQ.NEXTVAL INTO :V_SOURCE_CONTROL_ID;

    INSERT INTO <% database %>.OMD.SOURCE_CONTROL (SOURCE_CONTROL_ID, MODULE_ID, MODULE_INSTANCE_ID, INSERT_TIMESTAMP, START_VALUE, END_VALUE)
    VALUES (:V_SOURCE_CONTROL_ID, :V_MODULE_ID, :P_MODULE_INSTANCE_ID, SYSDATE(), LEFT(:P_START_VALUE, 100), LEFT(:P_END_VALUE, 100));

    RETURN V_SOURCE_CONTROL_ID;
END;
$$;

-- >>> 07_Procedures_Evaluation.sql
/*
 * DIRECT Framework - Snowflake edition
 * 07 Evaluation procedures
 *
 * BATCH_EVALUATION and MODULE_EVALUATION decide whether a new instance may run
 * (Proceed), is skipped (Cancel) or must not run (Abort), and roll back the data
 * of earlier failed instances before a new run proceeds. They return the
 * Internal Processing Status Code and leave the instance updated accordingly.
 */

CREATE OR REPLACE PROCEDURE <% database %>.OMD.BATCH_EVALUATION
(
    P_BATCH_INSTANCE_ID NUMBER
)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT = 'Evaluates a new Batch Instance: Abort when another instance of the Batch is executing, Cancel when the Batch is inactive or its previous instance was set to Cancel, otherwise Proceed after marking the Module Instances of earlier failed runs for rollback or skipping.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_BATCH_ID NUMBER;
    V_ACTIVE_INDICATOR VARCHAR;
    V_OTHER_EXECUTING NUMBER;
    V_PREVIOUS_EXECUTION_STATUS_CODE VARCHAR;
    V_PREVIOUS_NEXT_RUN_STATUS_CODE VARCHAR;
    V_LAST_GOOD_BATCH_INSTANCE_ID NUMBER;
    V_MESSAGE VARCHAR;
BEGIN
    V_BATCH_ID := <% database %>.OMD.GET_BATCH_ID_BY_BATCH_INSTANCE_ID(P_BATCH_INSTANCE_ID);

    IF (V_BATCH_ID IS NULL) THEN
        V_MESSAGE := 'The Batch Instance ' || COALESCE(TO_VARCHAR(P_BATCH_INSTANCE_ID), 'NULL') || ' does not exist.';
        CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, 0, :P_BATCH_INSTANCE_ID);
        RETURN 'Abort';
    END IF;

    -- Another instance of the same Batch that started earlier and is still executing: this one must not run.
    SELECT COUNT(*) INTO :V_OTHER_EXECUTING
    FROM <% database %>.OMD.BATCH_INSTANCE
    WHERE BATCH_ID = :V_BATCH_ID AND EXECUTION_STATUS_CODE = 'Executing' AND BATCH_INSTANCE_ID < :P_BATCH_INSTANCE_ID;

    IF (V_OTHER_EXECUTING > 0) THEN
        V_MESSAGE := 'Another instance of Batch ' || TO_VARCHAR(V_BATCH_ID) || ' is still executing. Batch Instance ' || TO_VARCHAR(P_BATCH_INSTANCE_ID) || ' is aborted.';
        CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, 0, :P_BATCH_INSTANCE_ID);
        CALL <% database %>.OMD.UPDATE_BATCH_INSTANCE(:P_BATCH_INSTANCE_ID, 'Abort');
        RETURN 'Abort';
    END IF;

    -- An inactive Batch is skipped.
    SELECT MAX(ACTIVE_INDICATOR) INTO :V_ACTIVE_INDICATOR FROM <% database %>.OMD.BATCH WHERE BATCH_ID = :V_BATCH_ID;
    IF (V_ACTIVE_INDICATOR = 'N') THEN
        CALL <% database %>.OMD.UPDATE_BATCH_INSTANCE(:P_BATCH_INSTANCE_ID, 'Cancel');
        RETURN 'Cancel';
    END IF;

    -- The previous instance of the Batch decides whether a rollback is needed.
    SELECT COALESCE(MAX_BY(EXECUTION_STATUS_CODE, BATCH_INSTANCE_ID), 'Succeeded'), COALESCE(MAX_BY(NEXT_RUN_STATUS_CODE, BATCH_INSTANCE_ID), 'Proceed')
    INTO :V_PREVIOUS_EXECUTION_STATUS_CODE, :V_PREVIOUS_NEXT_RUN_STATUS_CODE
    FROM <% database %>.OMD.BATCH_INSTANCE
    WHERE BATCH_ID = :V_BATCH_ID AND BATCH_INSTANCE_ID <> :P_BATCH_INSTANCE_ID AND EXECUTION_STATUS_CODE <> 'Executing';

    IF (V_PREVIOUS_NEXT_RUN_STATUS_CODE = 'Cancel') THEN
        -- A one-off skip, set by an administrator on the previous instance.
        UPDATE <% database %>.OMD.BATCH_INSTANCE SET NEXT_RUN_STATUS_CODE = 'Proceed' WHERE BATCH_ID = :V_BATCH_ID AND NEXT_RUN_STATUS_CODE = 'Cancel' AND BATCH_INSTANCE_ID <> :P_BATCH_INSTANCE_ID;
        CALL <% database %>.OMD.UPDATE_BATCH_INSTANCE(:P_BATCH_INSTANCE_ID, 'Cancel');
        RETURN 'Cancel';
    END IF;

    IF (V_PREVIOUS_EXECUTION_STATUS_CODE <> 'Failed' AND V_PREVIOUS_NEXT_RUN_STATUS_CODE <> 'Rollback') THEN
        CALL <% database %>.OMD.UPDATE_BATCH_INSTANCE(:P_BATCH_INSTANCE_ID, 'Proceed');
        RETURN 'Proceed';
    END IF;

    -- Rollback. The Batch Instances since the last successful one are the failed runs.
    CALL <% database %>.OMD.UPDATE_BATCH_INSTANCE(:P_BATCH_INSTANCE_ID, 'Rollback');

    SELECT COALESCE(MAX(BATCH_INSTANCE_ID), 0) INTO :V_LAST_GOOD_BATCH_INSTANCE_ID
    FROM <% database %>.OMD.BATCH_INSTANCE
    WHERE BATCH_ID = :V_BATCH_ID AND EXECUTION_STATUS_CODE = 'Succeeded' AND NEXT_RUN_STATUS_CODE = 'Proceed' AND BATCH_INSTANCE_ID <> :P_BATCH_INSTANCE_ID;

    IF (V_PREVIOUS_NEXT_RUN_STATUS_CODE = 'Rollback') THEN
        -- Full rollback: every Module Instance of the failed runs is rolled back by the Module evaluation.
        UPDATE <% database %>.OMD.MODULE_INSTANCE
        SET NEXT_RUN_STATUS_CODE = 'Rollback'
        WHERE BATCH_INSTANCE_ID IN
        (
            SELECT BATCH_INSTANCE_ID FROM <% database %>.OMD.BATCH_INSTANCE
            WHERE BATCH_ID = :V_BATCH_ID AND BATCH_INSTANCE_ID > :V_LAST_GOOD_BATCH_INSTANCE_ID AND BATCH_INSTANCE_ID <> :P_BATCH_INSTANCE_ID AND EXECUTION_STATUS_CODE <> 'Executing'
        );
        V_MESSAGE := 'Full rollback: the Module Instances of the failed runs of Batch ' || TO_VARCHAR(V_BATCH_ID) || ' are marked for rollback.';
    ELSE
        -- Partial rollback: the Modules that succeeded in the failed runs are skipped, the failed ones are rolled back by the Module evaluation.
        UPDATE <% database %>.OMD.MODULE_INSTANCE
        SET NEXT_RUN_STATUS_CODE = 'Cancel'
        WHERE EXECUTION_STATUS_CODE <> 'Failed'
          AND BATCH_INSTANCE_ID IN
        (
            SELECT BATCH_INSTANCE_ID FROM <% database %>.OMD.BATCH_INSTANCE
            WHERE BATCH_ID = :V_BATCH_ID AND BATCH_INSTANCE_ID > :V_LAST_GOOD_BATCH_INSTANCE_ID AND BATCH_INSTANCE_ID <> :P_BATCH_INSTANCE_ID AND EXECUTION_STATUS_CODE <> 'Executing'
        );
        V_MESSAGE := 'Partial rollback: the Modules that succeeded in the failed runs of Batch ' || TO_VARCHAR(V_BATCH_ID) || ' are skipped, the failed ones are rolled back.';
    END IF;

    IF (<% database %>.OMD_METADATA.GET_SETTING_FLAG('LOG_TO_EVENT_LOG') = 'Y') THEN
        CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, 0, :P_BATCH_INSTANCE_ID);
    END IF;

    CALL <% database %>.OMD.UPDATE_BATCH_INSTANCE(:P_BATCH_INSTANCE_ID, 'Proceed');
    RETURN 'Proceed';
EXCEPTION
    WHEN OTHER THEN
        V_MESSAGE := 'Error in BATCH_EVALUATION: ' || SQLERRM;
        CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, 0, :P_BATCH_INSTANCE_ID, 1, TO_VARCHAR(:SQLCODE));
        CALL <% database %>.OMD.UPDATE_BATCH_INSTANCE(:P_BATCH_INSTANCE_ID, 'Failure');
        RETURN 'Abort';
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.MODULE_EVALUATION
(
    P_MODULE_INSTANCE_ID NUMBER
)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT = 'Evaluates a new Module Instance: Abort when another instance of the Module is executing or the Batch/Module relationship is missing, Cancel when the Module or the relationship is inactive or the previous run was set to Cancel, otherwise Proceed after rolling back the data of earlier failed instances (DELETE on the target data object by the Module Instance Id column).'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_MODULE_ID NUMBER;
    V_BATCH_ID NUMBER;
    V_MINIMUM_EXECUTING NUMBER;
    V_BATCH_MODULE_ACTIVE_INDICATOR VARCHAR;
    V_MODULE_ACTIVE_INDICATOR VARCHAR;
    V_LAST_MODULE_INSTANCE_ID NUMBER;
    V_LAST_EXECUTION_STATUS_CODE VARCHAR;
    V_LAST_NEXT_RUN_STATUS_CODE VARCHAR;
    V_LAST_GOOD_MODULE_INSTANCE_ID NUMBER;
    V_ROLLBACK_LIST VARCHAR;
    V_DATA_OBJECT_TARGET VARCHAR;
    V_COLUMN_NAME VARCHAR;
    V_STATEMENT VARCHAR;
    V_MESSAGE VARCHAR;
BEGIN
    V_MODULE_ID := <% database %>.OMD.GET_MODULE_ID_BY_MODULE_INSTANCE_ID(P_MODULE_INSTANCE_ID);

    IF (V_MODULE_ID IS NULL) THEN
        V_MESSAGE := 'The Module Instance ' || COALESCE(TO_VARCHAR(P_MODULE_INSTANCE_ID), 'NULL') || ' does not exist.';
        CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE);
        RETURN 'Abort';
    END IF;

    -- Only the first of several executing instances of the same Module may continue.
    SELECT MIN(MODULE_INSTANCE_ID) INTO :V_MINIMUM_EXECUTING
    FROM <% database %>.OMD.MODULE_INSTANCE
    WHERE MODULE_ID = :V_MODULE_ID AND EXECUTION_STATUS_CODE = 'Executing';

    IF (V_MINIMUM_EXECUTING <> P_MODULE_INSTANCE_ID) THEN
        V_MESSAGE := 'Another instance of Module ' || TO_VARCHAR(V_MODULE_ID) || ' is still executing. Module Instance ' || TO_VARCHAR(P_MODULE_INSTANCE_ID) || ' is aborted.';
        CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, :P_MODULE_INSTANCE_ID);
        CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:P_MODULE_INSTANCE_ID, 'Abort');
        RETURN 'Abort';
    END IF;

    -- A Module that runs from a Batch must be active for that Batch.
    V_BATCH_ID := <% database %>.OMD.GET_BATCH_ID_BY_MODULE_INSTANCE_ID(P_MODULE_INSTANCE_ID);

    IF (V_BATCH_ID <> 0) THEN
        V_BATCH_MODULE_ACTIVE_INDICATOR := <% database %>.OMD.GET_BATCH_MODULE_ACTIVE_INDICATOR_VALUE(V_BATCH_ID, V_MODULE_ID);
        IF (V_BATCH_MODULE_ACTIVE_INDICATOR = 'N') THEN
            CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:P_MODULE_INSTANCE_ID, 'Cancel');
            RETURN 'Cancel';
        END IF;
        IF (V_BATCH_MODULE_ACTIVE_INDICATOR = 'U') THEN
            V_MESSAGE := 'Module ' || TO_VARCHAR(V_MODULE_ID) || ' is not registered for Batch ' || TO_VARCHAR(V_BATCH_ID) || '. Module Instance ' || TO_VARCHAR(P_MODULE_INSTANCE_ID) || ' is aborted.';
            CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, :P_MODULE_INSTANCE_ID);
            CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:P_MODULE_INSTANCE_ID, 'Abort');
            RETURN 'Abort';
        END IF;
    END IF;

    -- An inactive Module is skipped.
    SELECT MAX(ACTIVE_INDICATOR) INTO :V_MODULE_ACTIVE_INDICATOR FROM <% database %>.OMD.MODULE WHERE MODULE_ID = :V_MODULE_ID;
    IF (V_MODULE_ACTIVE_INDICATOR = 'N') THEN
        CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:P_MODULE_INSTANCE_ID, 'Cancel');
        RETURN 'Cancel';
    END IF;

    -- The previous instance of the Module, in the same Batch (or stand-alone), decides whether a rollback is needed.
    SELECT COALESCE(MAX(mi.MODULE_INSTANCE_ID), 0) INTO :V_LAST_MODULE_INSTANCE_ID
    FROM <% database %>.OMD.MODULE_INSTANCE mi
    LEFT JOIN <% database %>.OMD.BATCH_INSTANCE bi ON mi.BATCH_INSTANCE_ID = bi.BATCH_INSTANCE_ID
    WHERE mi.MODULE_ID = :V_MODULE_ID
      AND mi.MODULE_INSTANCE_ID <> :P_MODULE_INSTANCE_ID
      AND mi.EXECUTION_STATUS_CODE NOT IN ('Executing', 'Aborted')
      AND COALESCE(bi.BATCH_ID, 0) = :V_BATCH_ID;

    SELECT COALESCE(MAX(EXECUTION_STATUS_CODE), 'Succeeded'), COALESCE(MAX(NEXT_RUN_STATUS_CODE), 'Proceed')
    INTO :V_LAST_EXECUTION_STATUS_CODE, :V_LAST_NEXT_RUN_STATUS_CODE
    FROM <% database %>.OMD.MODULE_INSTANCE
    WHERE MODULE_INSTANCE_ID = :V_LAST_MODULE_INSTANCE_ID AND :V_LAST_MODULE_INSTANCE_ID <> 0;

    IF (V_LAST_NEXT_RUN_STATUS_CODE = 'Cancel') THEN
        -- A one-off skip: the previous instance succeeded in a Batch that failed, or an administrator set it.
        UPDATE <% database %>.OMD.MODULE_INSTANCE SET NEXT_RUN_STATUS_CODE = 'Proceed' WHERE MODULE_INSTANCE_ID = :V_LAST_MODULE_INSTANCE_ID;
        CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:P_MODULE_INSTANCE_ID, 'Cancel');
        RETURN 'Cancel';
    END IF;

    IF (V_LAST_EXECUTION_STATUS_CODE <> 'Failed' AND V_LAST_NEXT_RUN_STATUS_CODE <> 'Rollback') THEN
        CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:P_MODULE_INSTANCE_ID, 'Proceed');
        RETURN 'Proceed';
    END IF;

    -- Rollback: remove the rows of the instances since the last good one from the target data object.
    CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:P_MODULE_INSTANCE_ID, 'Rollback');

    IF (V_BATCH_ID = 0) THEN
        SELECT COALESCE(MAX(mi.MODULE_INSTANCE_ID), 0) INTO :V_LAST_GOOD_MODULE_INSTANCE_ID
        FROM <% database %>.OMD.MODULE_INSTANCE mi
        LEFT JOIN <% database %>.OMD.BATCH_INSTANCE bi ON mi.BATCH_INSTANCE_ID = bi.BATCH_INSTANCE_ID
        WHERE mi.MODULE_ID = :V_MODULE_ID AND COALESCE(bi.BATCH_ID, 0) = 0
          AND mi.EXECUTION_STATUS_CODE = 'Succeeded' AND mi.NEXT_RUN_STATUS_CODE = 'Proceed';
    ELSE
        SELECT COALESCE(MAX(mi.MODULE_INSTANCE_ID), 0) INTO :V_LAST_GOOD_MODULE_INSTANCE_ID
        FROM <% database %>.OMD.MODULE_INSTANCE mi
        JOIN <% database %>.OMD.BATCH_INSTANCE bi ON mi.BATCH_INSTANCE_ID = bi.BATCH_INSTANCE_ID
        WHERE mi.MODULE_ID = :V_MODULE_ID AND bi.BATCH_ID = :V_BATCH_ID
          AND bi.EXECUTION_STATUS_CODE = 'Succeeded';
    END IF;

    SELECT LISTAGG(mi.MODULE_INSTANCE_ID, ',') WITHIN GROUP (ORDER BY mi.MODULE_INSTANCE_ID) INTO :V_ROLLBACK_LIST
    FROM <% database %>.OMD.MODULE_INSTANCE mi
    LEFT JOIN <% database %>.OMD.BATCH_INSTANCE bi ON mi.BATCH_INSTANCE_ID = bi.BATCH_INSTANCE_ID
    WHERE mi.MODULE_ID = :V_MODULE_ID
      AND COALESCE(bi.BATCH_ID, 0) = :V_BATCH_ID
      AND mi.MODULE_INSTANCE_ID > :V_LAST_GOOD_MODULE_INSTANCE_ID
      AND mi.MODULE_INSTANCE_ID <> :P_MODULE_INSTANCE_ID
      AND mi.EXECUTION_STATUS_CODE NOT IN ('Executing', 'Aborted');

    IF (V_ROLLBACK_LIST IS NOT NULL AND V_ROLLBACK_LIST <> '') THEN
        SELECT MAX(DATA_OBJECT_TARGET) INTO :V_DATA_OBJECT_TARGET FROM <% database %>.OMD.MODULE WHERE MODULE_ID = :V_MODULE_ID;
        V_COLUMN_NAME := COALESCE(NULLIF(<% database %>.OMD_METADATA.GET_SETTING('MODULE_INSTANCE_ID_COLUMN_NAME'), ''), 'MODULE_INSTANCE_ID');

        IF (V_DATA_OBJECT_TARGET IS NOT NULL AND V_DATA_OBJECT_TARGET <> 'N/A') THEN
            V_STATEMENT := 'DELETE FROM ' || V_DATA_OBJECT_TARGET || ' WHERE ' || V_COLUMN_NAME || ' IN (' || V_ROLLBACK_LIST || ')';
            EXECUTE IMMEDIATE :V_STATEMENT;
            V_MESSAGE := 'Rollback of Module Instance(s) ' || V_ROLLBACK_LIST || ': ' || V_STATEMENT;
        ELSE
            V_MESSAGE := 'Rollback of Module Instance(s) ' || V_ROLLBACK_LIST || ': the Module has no target data object, only the load windows are removed.';
        END IF;

        -- The load windows of the rolled back instances no longer count.
        V_STATEMENT := 'DELETE FROM <% database %>.OMD.SOURCE_CONTROL WHERE MODULE_INSTANCE_ID IN (' || V_ROLLBACK_LIST || ')';
        EXECUTE IMMEDIATE :V_STATEMENT;

        -- The rolled back instances keep their execution status; their next run status is settled.
        V_STATEMENT := 'UPDATE <% database %>.OMD.MODULE_INSTANCE SET NEXT_RUN_STATUS_CODE = ''Proceed'' WHERE MODULE_INSTANCE_ID IN (' || V_ROLLBACK_LIST || ')';
        EXECUTE IMMEDIATE :V_STATEMENT;

        IF (<% database %>.OMD_METADATA.GET_SETTING_FLAG('LOG_TO_EVENT_LOG') = 'Y') THEN
            CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, :P_MODULE_INSTANCE_ID);
        END IF;
    END IF;

    CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:P_MODULE_INSTANCE_ID, 'Proceed');
    RETURN 'Proceed';
EXCEPTION
    WHEN OTHER THEN
        V_MESSAGE := 'Error in MODULE_EVALUATION: ' || SQLERRM;
        CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, :P_MODULE_INSTANCE_ID, 0, 1, TO_VARCHAR(:SQLCODE));
        CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:P_MODULE_INSTANCE_ID, 'Failure');
        RETURN 'Abort';
END;
$$;

-- >>> 08_Procedures_Run.sql
/*
 * DIRECT Framework - Snowflake edition
 * 08 Run procedures
 *
 * RUN_MODULE runs one Module: it creates and evaluates the Module Instance,
 * determines the load window, runs the executable and records the outcome.
 * RUN_BATCH runs a Batch: its Modules in sequence, then its child Batches in
 * sequence, and closes the Batch Instance.
 *
 * The executable contract. The EXECUTABLE of a Module is a SQL statement that
 * runs in the repository database through EXECUTE IMMEDIATE. Before it runs,
 * these tokens are replaced by values:
 *
 *   :ModuleInstanceId     the Module Instance Id of this run, as a number
 *   :StartValue           the end value of the previous load window, as a quoted string
 *   :EndValue             the end value of this load window, as a quoted string
 *   :ConsistencyDateTime  NULL (consistency timestamps are not part of this edition)
 *
 * For example: CALL MY_DB.DV.SP_SAT_CUSTOMER(:ModuleInstanceId, :EndValue)
 *
 * When the executable returns a single value (a procedure that returns a row
 * count, or an INSERT), that value is recorded as the number of rows inserted.
 */

CREATE OR REPLACE PROCEDURE <% database %>.OMD.RUN_MODULE
(
    P_MODULE_CODE        VARCHAR,
    P_BATCH_INSTANCE_ID  NUMBER DEFAULT 0,
    P_EXECUTION_CONTEXT  VARCHAR DEFAULT '',
    P_QUERY              VARCHAR DEFAULT NULL,
    P_END_VALUE          VARCHAR DEFAULT NULL
)
RETURNS OBJECT
LANGUAGE SQL
COMMENT = 'Runs a Module: creates and evaluates the Module Instance, runs the executable (or the given query) with the load window, and records the outcome. P_END_VALUE overrides the end of the load window. Returns an object with MODULE_INSTANCE_ID, INTERNAL_PROCESSING_STATUS_CODE, EXECUTION_STATUS_CODE, START_VALUE, END_VALUE, ROWS_INSERTED and EVENT_DETAIL. Raises an error after the bookkeeping when the Module failed, it runs stand-alone (no Batch Instance) and the setting THROW_ON_FAILURE is Y; inside a Batch the failure is returned to RUN_BATCH.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_MODULE_INSTANCE_ID NUMBER;
    V_MODULE_ID NUMBER;
    V_STATUS VARCHAR;
    V_EXECUTABLE VARCHAR;
    V_DATA_OBJECT_SOURCE VARCHAR;
    V_START_VALUE VARCHAR;
    V_END_VALUE VARCHAR;
    V_LOAD_WINDOW_ATTRIBUTE VARCHAR;
    V_FORMAT VARCHAR;
    V_STATEMENT VARCHAR;
    V_RESULT RESULTSET;
    V_FIRST_VALUE VARCHAR;
    V_ROWS NUMBER DEFAULT 0;
    V_MESSAGE VARCHAR;
    V_RETURN_CODE VARCHAR;
    MODULE_FAILED EXCEPTION (-20002, 'The Module failed. The event log holds the error.');
BEGIN
    CALL <% database %>.OMD.CREATE_MODULE_INSTANCE(:P_MODULE_CODE, :P_BATCH_INSTANCE_ID, :P_EXECUTION_CONTEXT, :P_QUERY) INTO :V_MODULE_INSTANCE_ID;

    IF (V_MODULE_INSTANCE_ID IS NULL) THEN
        RETURN OBJECT_CONSTRUCT('MODULE_CODE', P_MODULE_CODE, 'MODULE_INSTANCE_ID', NULL, 'INTERNAL_PROCESSING_STATUS_CODE', 'Abort', 'EXECUTION_STATUS_CODE', 'Aborted',
            'EVENT_DETAIL', 'The Module Instance could not be created; see the event log.');
    END IF;

    CALL <% database %>.OMD.MODULE_EVALUATION(:V_MODULE_INSTANCE_ID) INTO :V_STATUS;

    IF (V_STATUS <> 'Proceed') THEN
        RETURN OBJECT_CONSTRUCT('MODULE_CODE', P_MODULE_CODE, 'MODULE_INSTANCE_ID', V_MODULE_INSTANCE_ID, 'INTERNAL_PROCESSING_STATUS_CODE', V_STATUS,
            'EXECUTION_STATUS_CODE', IFF(V_STATUS = 'Cancel', 'Cancelled', 'Aborted'), 'ROWS_INSERTED', 0);
    END IF;

    -- The executable and the source data object of the Module.
    V_MODULE_ID := <% database %>.OMD.GET_MODULE_ID_BY_MODULE_INSTANCE_ID(V_MODULE_INSTANCE_ID);
    SELECT MAX(EXECUTABLE), MAX(DATA_OBJECT_SOURCE) INTO :V_EXECUTABLE, :V_DATA_OBJECT_SOURCE FROM <% database %>.OMD.MODULE WHERE MODULE_ID = :V_MODULE_ID;
    IF (P_QUERY IS NOT NULL) THEN
        V_EXECUTABLE := P_QUERY;
    END IF;

    -- The load window: from the end of the previous window to now, or to the maximum of the load window attribute in the source.
    V_FORMAT := COALESCE(<% database %>.OMD_METADATA.GET_SETTING('TIMESTAMP_FORMAT'), 'YYYY-MM-DD HH24:MI:SS.FF7');
    V_START_VALUE := COALESCE(<% database %>.OMD.GET_MODULE_LOAD_WINDOW_VALUE(V_MODULE_ID, 2), <% database %>.OMD_METADATA.GET_SETTING('DEFAULT_START_VALUE'), '1900-01-01 00:00:00.0000000');
    V_END_VALUE := P_END_VALUE;

    IF (V_END_VALUE IS NULL) THEN
        V_LOAD_WINDOW_ATTRIBUTE := NULLIF(TRIM(COALESCE(<% database %>.OMD_METADATA.GET_SETTING('LOAD_WINDOW_ATTRIBUTE_NAME'), '')), '');
        IF (V_LOAD_WINDOW_ATTRIBUTE IS NOT NULL AND V_DATA_OBJECT_SOURCE IS NOT NULL AND V_DATA_OBJECT_SOURCE <> 'N/A') THEN
            BEGIN
                V_STATEMENT := 'SELECT TO_VARCHAR(MAX(' || V_LOAD_WINDOW_ATTRIBUTE || '), ''' || V_FORMAT || ''') FROM ' || V_DATA_OBJECT_SOURCE;
                V_RESULT := (EXECUTE IMMEDIATE :V_STATEMENT);
                LET V_WINDOW_CURSOR CURSOR FOR V_RESULT;
                OPEN V_WINDOW_CURSOR;
                FETCH V_WINDOW_CURSOR INTO V_END_VALUE;
                CLOSE V_WINDOW_CURSOR;
            EXCEPTION
                WHEN OTHER THEN
                    V_END_VALUE := NULL;
            END;
        END IF;
        IF (V_END_VALUE IS NULL) THEN
            V_END_VALUE := TO_VARCHAR(SYSDATE(), V_FORMAT);
        END IF;
    END IF;

    -- Run the executable with the tokens replaced.
    V_STATEMENT := COALESCE(V_EXECUTABLE, 'SELECT NULL');
    V_STATEMENT := REPLACE(V_STATEMENT, ':ModuleInstanceId', TO_VARCHAR(V_MODULE_INSTANCE_ID));
    V_STATEMENT := REPLACE(V_STATEMENT, ':StartValue', '''' || REPLACE(V_START_VALUE, '''', '''''') || '''');
    V_STATEMENT := REPLACE(V_STATEMENT, ':EndValue', '''' || REPLACE(V_END_VALUE, '''', '''''') || '''');
    V_STATEMENT := REPLACE(V_STATEMENT, ':ConsistencyDateTime', 'NULL');

    BEGIN
        V_RESULT := (EXECUTE IMMEDIATE :V_STATEMENT);
        LET V_CURSOR CURSOR FOR V_RESULT;
        OPEN V_CURSOR;
        FETCH V_CURSOR INTO V_FIRST_VALUE;
        CLOSE V_CURSOR;
        V_ROWS := COALESCE(TRY_TO_NUMBER(V_FIRST_VALUE), 0);
    EXCEPTION
        WHEN OTHER THEN
            V_MESSAGE := LEFT('Error running Module ''' || P_MODULE_CODE || ''' (Module Instance ' || TO_VARCHAR(V_MODULE_INSTANCE_ID) || '): ' || SQLERRM || ' Statement: ' || V_STATEMENT, 4000);
            V_RETURN_CODE := TO_VARCHAR(SQLCODE);
            CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, :V_MODULE_INSTANCE_ID, :P_BATCH_INSTANCE_ID, 2, :V_RETURN_CODE);
            CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:V_MODULE_INSTANCE_ID, 'Failure');
            IF (COALESCE(P_BATCH_INSTANCE_ID, 0) = 0 AND <% database %>.OMD_METADATA.GET_SETTING_FLAG('THROW_ON_FAILURE') = 'Y') THEN
                RAISE MODULE_FAILED;
            END IF;
            RETURN OBJECT_CONSTRUCT('MODULE_CODE', P_MODULE_CODE, 'MODULE_INSTANCE_ID', V_MODULE_INSTANCE_ID, 'INTERNAL_PROCESSING_STATUS_CODE', 'Proceed', 'EXECUTION_STATUS_CODE', 'Failed',
                'START_VALUE', V_START_VALUE, 'END_VALUE', V_END_VALUE, 'ROWS_INSERTED', 0, 'EVENT_DETAIL', V_MESSAGE);
    END;

    CALL <% database %>.OMD.SET_SOURCE_CONTROL_VALUES(:V_MODULE_INSTANCE_ID, :V_START_VALUE, :V_END_VALUE);
    CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:V_MODULE_INSTANCE_ID, 'Success', 0, :V_ROWS);

    RETURN OBJECT_CONSTRUCT('MODULE_CODE', P_MODULE_CODE, 'MODULE_INSTANCE_ID', V_MODULE_INSTANCE_ID, 'INTERNAL_PROCESSING_STATUS_CODE', 'Proceed', 'EXECUTION_STATUS_CODE', 'Succeeded',
        'START_VALUE', V_START_VALUE, 'END_VALUE', V_END_VALUE, 'ROWS_INSERTED', V_ROWS);
EXCEPTION
    WHEN MODULE_FAILED THEN
        RAISE;
    WHEN OTHER THEN
        V_MESSAGE := LEFT('Error in RUN_MODULE for Module ''' || COALESCE(P_MODULE_CODE, '') || ''': ' || SQLERRM, 4000);
        V_RETURN_CODE := TO_VARCHAR(SQLCODE);
        CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, COALESCE(:V_MODULE_INSTANCE_ID, 0), :P_BATCH_INSTANCE_ID, 1, :V_RETURN_CODE);
        IF (V_MODULE_INSTANCE_ID IS NOT NULL) THEN
            CALL <% database %>.OMD.UPDATE_MODULE_INSTANCE(:V_MODULE_INSTANCE_ID, 'Failure');
        END IF;
        IF (COALESCE(P_BATCH_INSTANCE_ID, 0) = 0 AND <% database %>.OMD_METADATA.GET_SETTING_FLAG('THROW_ON_FAILURE') = 'Y') THEN
            RAISE MODULE_FAILED;
        END IF;
        RETURN OBJECT_CONSTRUCT('MODULE_CODE', P_MODULE_CODE, 'MODULE_INSTANCE_ID', V_MODULE_INSTANCE_ID, 'INTERNAL_PROCESSING_STATUS_CODE', 'Proceed', 'EXECUTION_STATUS_CODE', 'Failed',
            'ROWS_INSERTED', 0, 'EVENT_DETAIL', V_MESSAGE);
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.RUN_BATCH
(
    P_BATCH_CODE                VARCHAR,
    P_PARENT_BATCH_INSTANCE_ID  NUMBER DEFAULT 0,
    P_EXECUTION_CONTEXT         VARCHAR DEFAULT '',
    P_END_VALUE                 VARCHAR DEFAULT NULL
)
RETURNS OBJECT
LANGUAGE SQL
COMMENT = 'Runs a Batch: creates and evaluates the Batch Instance, runs the active Modules of the Batch in sequence and then the active child Batches in sequence, and closes the Batch Instance. P_END_VALUE is passed to every Module as the end of its load window. Returns an object with BATCH_INSTANCE_ID, INTERNAL_PROCESSING_STATUS_CODE, EXECUTION_STATUS_CODE, MODULES, MODULES_FAILED, CHILD_BATCHES and CHILD_BATCHES_FAILED. Raises an error at the end when a Module failed and the setting THROW_ON_FAILURE is Y (top-level Batch only).'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_BATCH_INSTANCE_ID NUMBER;
    V_BATCH_ID NUMBER;
    V_STATUS VARCHAR;
    V_MODULE_RESULT OBJECT;
    V_BATCH_RESULT OBJECT;
    V_MODULES NUMBER DEFAULT 0;
    V_MODULES_FAILED NUMBER DEFAULT 0;
    V_CHILD_BATCHES NUMBER DEFAULT 0;
    V_CHILD_BATCHES_FAILED NUMBER DEFAULT 0;
    V_STOP VARCHAR DEFAULT 'N';
    V_STOP_ON_FAILURE VARCHAR;
    V_EXECUTION_STATUS_CODE VARCHAR;
    V_MODULE_LIST RESULTSET;
    V_CHILD_LIST RESULTSET;
    V_MODULE_CODE VARCHAR;
    V_CHILD_BATCH_CODE VARCHAR;
    V_MESSAGE VARCHAR;
    V_RETURN_CODE VARCHAR;
    BATCH_FAILED EXCEPTION (-20001, 'The Batch ended with failures.');
BEGIN
    CALL <% database %>.OMD.CREATE_BATCH_INSTANCE(:P_BATCH_CODE, :P_PARENT_BATCH_INSTANCE_ID, :P_EXECUTION_CONTEXT) INTO :V_BATCH_INSTANCE_ID;

    IF (V_BATCH_INSTANCE_ID IS NULL) THEN
        RETURN OBJECT_CONSTRUCT('BATCH_CODE', P_BATCH_CODE, 'BATCH_INSTANCE_ID', NULL, 'INTERNAL_PROCESSING_STATUS_CODE', 'Abort', 'EXECUTION_STATUS_CODE', 'Aborted',
            'EVENT_DETAIL', 'The Batch Instance could not be created; see the event log.');
    END IF;

    CALL <% database %>.OMD.BATCH_EVALUATION(:V_BATCH_INSTANCE_ID) INTO :V_STATUS;

    IF (V_STATUS <> 'Proceed') THEN
        RETURN OBJECT_CONSTRUCT('BATCH_CODE', P_BATCH_CODE, 'BATCH_INSTANCE_ID', V_BATCH_INSTANCE_ID, 'INTERNAL_PROCESSING_STATUS_CODE', V_STATUS,
            'EXECUTION_STATUS_CODE', IFF(V_STATUS = 'Cancel', 'Cancelled', 'Aborted'), 'MODULES', 0, 'MODULES_FAILED', 0, 'CHILD_BATCHES', 0, 'CHILD_BATCHES_FAILED', 0);
    END IF;

    V_BATCH_ID := <% database %>.OMD.GET_BATCH_ID_BY_BATCH_INSTANCE_ID(V_BATCH_INSTANCE_ID);
    V_STOP_ON_FAILURE := <% database %>.OMD_METADATA.GET_SETTING_FLAG('STOP_BATCH_ON_MODULE_FAILURE');

    -- The Modules of the Batch, in sequence.
    V_MODULE_LIST := (
        SELECT m.MODULE_CODE
        FROM <% database %>.OMD.BATCH_MODULE bm
        JOIN <% database %>.OMD.MODULE m ON bm.MODULE_ID = m.MODULE_ID
        WHERE bm.BATCH_ID = :V_BATCH_ID AND bm.ACTIVE_INDICATOR = 'Y'
        ORDER BY bm.SEQUENCE, m.MODULE_CODE
    );

    LET V_MODULE_CURSOR CURSOR FOR V_MODULE_LIST;
    FOR V_MODULE IN V_MODULE_CURSOR DO
        IF (V_STOP = 'Y') THEN
            BREAK;
        END IF;
        V_MODULES := V_MODULES + 1;
        V_MODULE_CODE := V_MODULE.MODULE_CODE;
        CALL <% database %>.OMD.RUN_MODULE(:V_MODULE_CODE, :V_BATCH_INSTANCE_ID, :P_EXECUTION_CONTEXT, NULL, :P_END_VALUE) INTO :V_MODULE_RESULT;
        IF (GET(V_MODULE_RESULT, 'EXECUTION_STATUS_CODE')::VARCHAR = 'Failed') THEN
            V_MODULES_FAILED := V_MODULES_FAILED + 1;
            IF (V_STOP_ON_FAILURE = 'Y') THEN
                V_STOP := 'Y';
            END IF;
        END IF;
    END FOR;

    -- The child Batches, in sequence, with this Batch Instance as parent.
    IF (V_STOP = 'N') THEN
        V_CHILD_LIST := (
            SELECT b.BATCH_CODE
            FROM <% database %>.OMD.BATCH_HIERARCHY bh
            JOIN <% database %>.OMD.BATCH b ON bh.BATCH_ID = b.BATCH_ID
            WHERE bh.PARENT_BATCH_ID = :V_BATCH_ID AND bh.ACTIVE_INDICATOR = 'Y'
            ORDER BY bh.SEQUENCE, b.BATCH_CODE
        );

        LET V_CHILD_CURSOR CURSOR FOR V_CHILD_LIST;
        FOR V_CHILD IN V_CHILD_CURSOR DO
            IF (V_STOP = 'Y') THEN
                BREAK;
            END IF;
            V_CHILD_BATCHES := V_CHILD_BATCHES + 1;
            V_CHILD_BATCH_CODE := V_CHILD.BATCH_CODE;
            CALL <% database %>.OMD.RUN_BATCH(:V_CHILD_BATCH_CODE, :V_BATCH_INSTANCE_ID, :P_EXECUTION_CONTEXT, :P_END_VALUE) INTO :V_BATCH_RESULT;
            IF (GET(V_BATCH_RESULT, 'EXECUTION_STATUS_CODE')::VARCHAR = 'Failed') THEN
                V_CHILD_BATCHES_FAILED := V_CHILD_BATCHES_FAILED + 1;
                IF (V_STOP_ON_FAILURE = 'Y') THEN
                    V_STOP := 'Y';
                END IF;
            END IF;
        END FOR;
    END IF;

    -- Close the Batch Instance.
    IF ((V_MODULES_FAILED > 0 OR V_CHILD_BATCHES_FAILED > 0) AND <% database %>.OMD_METADATA.GET_SETTING_FLAG('FAIL_BATCH_ON_MODULE_FAILURE') = 'Y') THEN
        V_EXECUTION_STATUS_CODE := 'Failed';
        CALL <% database %>.OMD.UPDATE_BATCH_INSTANCE(:V_BATCH_INSTANCE_ID, 'Failure');
    ELSE
        V_EXECUTION_STATUS_CODE := 'Succeeded';
        CALL <% database %>.OMD.UPDATE_BATCH_INSTANCE(:V_BATCH_INSTANCE_ID, 'Success');
    END IF;

    IF (V_EXECUTION_STATUS_CODE = 'Failed' AND COALESCE(P_PARENT_BATCH_INSTANCE_ID, 0) = 0 AND <% database %>.OMD_METADATA.GET_SETTING_FLAG('THROW_ON_FAILURE') = 'Y') THEN
        RAISE BATCH_FAILED;
    END IF;

    RETURN OBJECT_CONSTRUCT('BATCH_CODE', P_BATCH_CODE, 'BATCH_INSTANCE_ID', V_BATCH_INSTANCE_ID, 'INTERNAL_PROCESSING_STATUS_CODE', 'Proceed', 'EXECUTION_STATUS_CODE', V_EXECUTION_STATUS_CODE,
        'MODULES', V_MODULES, 'MODULES_FAILED', V_MODULES_FAILED, 'CHILD_BATCHES', V_CHILD_BATCHES, 'CHILD_BATCHES_FAILED', V_CHILD_BATCHES_FAILED);
EXCEPTION
    WHEN BATCH_FAILED THEN
        RAISE;
    WHEN OTHER THEN
        V_MESSAGE := LEFT('Error in RUN_BATCH for Batch ''' || COALESCE(P_BATCH_CODE, '') || ''': ' || SQLERRM, 4000);
        V_RETURN_CODE := TO_VARCHAR(SQLCODE);
        CALL <% database %>.OMD.INSERT_INTO_EVENT_LOG(:V_MESSAGE, 0, COALESCE(:V_BATCH_INSTANCE_ID, 0), 1, :V_RETURN_CODE);
        IF (V_BATCH_INSTANCE_ID IS NOT NULL) THEN
            CALL <% database %>.OMD.UPDATE_BATCH_INSTANCE(:V_BATCH_INSTANCE_ID, 'Failure');
        END IF;
        RAISE;
END;
$$;

-- >>> 09_Procedures_Queue.sql
/*
 * DIRECT Framework - Snowflake edition
 * 09 Queue procedures
 *
 * The queue is a Snowflake Task per Batch that calls RUN_BATCH on a schedule:
 * the trickle feed. START_QUEUE creates (or replaces) and resumes the Task,
 * STOP_QUEUE suspends it, REMOVE_QUEUE drops it. The Task is serverless unless
 * a warehouse is given. A run that starts while the previous one is still
 * running is skipped by Snowflake (tasks do not overlap by default), and the
 * Batch evaluation aborts a second instance in any case.
 *
 * The owner of these procedures needs CREATE TASK on the OMD schema and, for
 * serverless Tasks, EXECUTE MANAGED TASK on the account; EXECUTE TASK on the
 * account is needed to resume a Task.
 */

CREATE OR REPLACE FUNCTION <% database %>.OMD.GET_QUEUE_TASK_NAME(P_BATCH_CODE VARCHAR)
RETURNS VARCHAR
AS
$$
    'QUEUE_' || UPPER(REGEXP_REPLACE(P_BATCH_CODE, '[^A-Za-z0-9_]', '_'))
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.START_QUEUE
(
    P_BATCH_CODE        VARCHAR,
    P_INTERVAL_MINUTES  NUMBER DEFAULT 15,
    P_WAREHOUSE         VARCHAR DEFAULT NULL
)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT = 'Creates or replaces the Task that runs the Batch every P_INTERVAL_MINUTES minutes (serverless, or on P_WAREHOUSE when given) and resumes it.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_TASK VARCHAR;
    V_STATEMENT VARCHAR;
    V_SIZE VARCHAR;
BEGIN
    IF (<% database %>.OMD.GET_BATCH_ID_BY_CODE(P_BATCH_CODE) IS NULL) THEN
        RETURN 'The Batch ''' || COALESCE(P_BATCH_CODE, '') || ''' is not registered.';
    END IF;
    IF (P_INTERVAL_MINUTES IS NULL OR P_INTERVAL_MINUTES < 1) THEN
        RETURN 'The interval must be at least 1 minute.';
    END IF;

    V_TASK := '<% database %>.OMD.' || <% database %>.OMD.GET_QUEUE_TASK_NAME(P_BATCH_CODE);
    V_SIZE := COALESCE(<% database %>.OMD_METADATA.GET_SETTING('QUEUE_WAREHOUSE_SIZE'), 'XSMALL');

    V_STATEMENT := 'CREATE OR REPLACE TASK ' || V_TASK
        || IFF(P_WAREHOUSE IS NULL, ' USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = ''' || V_SIZE || '''', ' WAREHOUSE = ' || P_WAREHOUSE)
        || ' SCHEDULE = ''' || TO_VARCHAR(P_INTERVAL_MINUTES) || ' MINUTE'''
        || ' ALLOW_OVERLAPPING_EXECUTION = FALSE'
        || ' COMMENT = ''DIRECT queue for Batch ' || REPLACE(P_BATCH_CODE, '''', '''''') || ''''
        || ' AS CALL <% database %>.OMD.RUN_BATCH(''' || REPLACE(P_BATCH_CODE, '''', '''''') || ''', 0, ''Task ' || <% database %>.OMD.GET_QUEUE_TASK_NAME(P_BATCH_CODE) || ''')';
    EXECUTE IMMEDIATE :V_STATEMENT;

    V_STATEMENT := 'ALTER TASK ' || V_TASK || ' RESUME';
    EXECUTE IMMEDIATE :V_STATEMENT;

    RETURN 'Task ' || V_TASK || ' runs Batch ''' || P_BATCH_CODE || ''' every ' || TO_VARCHAR(P_INTERVAL_MINUTES) || ' minute(s).';
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.STOP_QUEUE
(
    P_BATCH_CODE VARCHAR
)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT = 'Suspends the Task of the Batch. A run that is in progress completes.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_TASK VARCHAR;
    V_STATEMENT VARCHAR;
BEGIN
    V_TASK := '<% database %>.OMD.' || <% database %>.OMD.GET_QUEUE_TASK_NAME(P_BATCH_CODE);
    V_STATEMENT := 'ALTER TASK IF EXISTS ' || V_TASK || ' SUSPEND';
    EXECUTE IMMEDIATE :V_STATEMENT;
    RETURN 'Task ' || V_TASK || ' is suspended.';
END;
$$;

CREATE OR REPLACE PROCEDURE <% database %>.OMD.REMOVE_QUEUE
(
    P_BATCH_CODE VARCHAR
)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT = 'Drops the Task of the Batch.'
EXECUTE AS OWNER
AS
$$
DECLARE
    V_TASK VARCHAR;
    V_STATEMENT VARCHAR;
BEGIN
    V_TASK := '<% database %>.OMD.' || <% database %>.OMD.GET_QUEUE_TASK_NAME(P_BATCH_CODE);
    V_STATEMENT := 'DROP TASK IF EXISTS ' || V_TASK;
    EXECUTE IMMEDIATE :V_STATEMENT;
    RETURN 'Task ' || V_TASK || ' is removed.';
END;
$$;

-- >>> 10_Views.sql
/*
 * DIRECT Framework - Snowflake edition
 * 10 Processing and reporting views
 */

CREATE OR REPLACE VIEW <% database %>.OMD_PROCESSING.VW_BATCH_HIERARCHY AS
SELECT
    p.BATCH_ID    AS PARENT_BATCH_ID,
    p.BATCH_CODE  AS PARENT_BATCH_CODE,
    c.BATCH_ID    AS BATCH_ID,
    c.BATCH_CODE  AS BATCH_CODE,
    bh.SEQUENCE,
    bh.ACTIVE_INDICATOR
FROM <% database %>.OMD.BATCH_HIERARCHY bh
JOIN <% database %>.OMD.BATCH p ON bh.PARENT_BATCH_ID = p.BATCH_ID
JOIN <% database %>.OMD.BATCH c ON bh.BATCH_ID = c.BATCH_ID;

CREATE OR REPLACE VIEW <% database %>.OMD_PROCESSING.VW_BATCH_MODULE AS
SELECT
    b.BATCH_ID,
    b.BATCH_CODE,
    m.MODULE_ID,
    m.MODULE_CODE,
    m.MODULE_TYPE,
    m.AREA_CODE,
    bm.SEQUENCE,
    bm.ACTIVE_INDICATOR,
    m.DATA_OBJECT_SOURCE,
    m.DATA_OBJECT_TARGET,
    m.EXECUTABLE
FROM <% database %>.OMD.BATCH_MODULE bm
JOIN <% database %>.OMD.BATCH b ON bm.BATCH_ID = b.BATCH_ID
JOIN <% database %>.OMD.MODULE m ON bm.MODULE_ID = m.MODULE_ID;

-- The active on-demand Batches that are not executing, in the order of their last run (the oldest first).
CREATE OR REPLACE VIEW <% database %>.OMD_PROCESSING.VW_QUEUE_BATCH_PROCESSING AS
SELECT
    b.BATCH_ID,
    b.BATCH_CODE,
    COALESCE(MAX(bi.END_TIMESTAMP), '0001-01-01'::TIMESTAMP_NTZ) AS END_TIMESTAMP,
    ROW_NUMBER() OVER (ORDER BY COALESCE(MAX(bi.END_TIMESTAMP), '0001-01-01'::TIMESTAMP_NTZ)) AS QUEUE_ORDER
FROM <% database %>.OMD.BATCH b
LEFT JOIN <% database %>.OMD.BATCH_INSTANCE bi ON b.BATCH_ID = bi.BATCH_ID
WHERE b.BATCH_ID <> 0
  AND b.ACTIVE_INDICATOR = 'Y'
  AND b.FREQUENCY_CODE = 'On-demand'
  AND NOT EXISTS (SELECT 1 FROM <% database %>.OMD.BATCH_INSTANCE x WHERE x.BATCH_ID = b.BATCH_ID AND x.EXECUTION_STATUS_CODE = 'Executing')
GROUP BY b.BATCH_ID, b.BATCH_CODE;

CREATE OR REPLACE VIEW <% database %>.OMD_REPORTING.VW_EXECUTION_LOG_BATCH_INSTANCE AS
SELECT
    bi.BATCH_INSTANCE_ID,
    b.BATCH_CODE,
    bi.PARENT_BATCH_INSTANCE_ID,
    bi.EXECUTION_CONTEXT,
    bi.START_TIMESTAMP,
    bi.END_TIMESTAMP,
    DATEDIFF(second, bi.START_TIMESTAMP, bi.END_TIMESTAMP) AS EXECUTION_TIME,
    bi.INTERNAL_PROCESSING_CODE,
    bi.NEXT_RUN_STATUS_CODE,
    bi.EXECUTION_STATUS_CODE,
    es.EXECUTION_STATUS_DESCRIPTION
FROM <% database %>.OMD.BATCH_INSTANCE bi
JOIN <% database %>.OMD.BATCH b ON bi.BATCH_ID = b.BATCH_ID
LEFT JOIN <% database %>.OMD_METADATA.EXECUTION_STATUS es ON bi.EXECUTION_STATUS_CODE = es.EXECUTION_STATUS_CODE
WHERE bi.BATCH_INSTANCE_ID <> 0;

CREATE OR REPLACE VIEW <% database %>.OMD_REPORTING.VW_EXECUTION_LOG_MODULE_INSTANCE AS
SELECT
    mi.MODULE_INSTANCE_ID,
    m.MODULE_CODE,
    m.MODULE_TYPE,
    m.AREA_CODE,
    mi.BATCH_INSTANCE_ID,
    b.BATCH_CODE,
    mi.EXECUTION_CONTEXT,
    mi.START_TIMESTAMP,
    mi.END_TIMESTAMP,
    DATEDIFF(second, mi.START_TIMESTAMP, mi.END_TIMESTAMP) AS EXECUTION_TIME,
    mi.INTERNAL_PROCESSING_CODE,
    mi.NEXT_RUN_STATUS_CODE,
    mi.EXECUTION_STATUS_CODE,
    es.EXECUTION_STATUS_DESCRIPTION,
    mi.ROWS_INPUT,
    mi.ROWS_INSERTED,
    mi.ROWS_UPDATED,
    mi.ROWS_DELETED,
    mi.ROWS_DISCARDED,
    mi.ROWS_REJECTED,
    sc.START_VALUE,
    sc.END_VALUE
FROM <% database %>.OMD.MODULE_INSTANCE mi
JOIN <% database %>.OMD.MODULE m ON mi.MODULE_ID = m.MODULE_ID
LEFT JOIN <% database %>.OMD.BATCH_INSTANCE bi ON mi.BATCH_INSTANCE_ID = bi.BATCH_INSTANCE_ID
LEFT JOIN <% database %>.OMD.BATCH b ON bi.BATCH_ID = b.BATCH_ID
LEFT JOIN <% database %>.OMD_METADATA.EXECUTION_STATUS es ON mi.EXECUTION_STATUS_CODE = es.EXECUTION_STATUS_CODE
LEFT JOIN <% database %>.OMD.SOURCE_CONTROL sc ON mi.MODULE_INSTANCE_ID = sc.MODULE_INSTANCE_ID
WHERE mi.MODULE_INSTANCE_ID <> 0;

CREATE OR REPLACE VIEW <% database %>.OMD_REPORTING.VW_EXECUTION_EVENT_LOG AS
SELECT
    el.EVENT_ID,
    el.BATCH_INSTANCE_ID,
    b.BATCH_CODE,
    el.MODULE_INSTANCE_ID,
    m.MODULE_CODE,
    el.EVENT_TYPE_CODE,
    et.EVENT_TYPE_DESCRIPTION,
    el.EVENT_TIMESTAMP,
    el.EVENT_RETURN_CODE,
    el.EVENT_DETAIL,
    el.ERROR_BITMAP
FROM <% database %>.OMD.EVENT_LOG el
LEFT JOIN <% database %>.OMD_METADATA.EVENT_TYPE et ON el.EVENT_TYPE_CODE = et.EVENT_TYPE_CODE
LEFT JOIN <% database %>.OMD.BATCH_INSTANCE bi ON el.BATCH_INSTANCE_ID = bi.BATCH_INSTANCE_ID
LEFT JOIN <% database %>.OMD.BATCH b ON bi.BATCH_ID = b.BATCH_ID
LEFT JOIN <% database %>.OMD.MODULE_INSTANCE mi ON el.MODULE_INSTANCE_ID = mi.MODULE_INSTANCE_ID
LEFT JOIN <% database %>.OMD.MODULE m ON mi.MODULE_ID = m.MODULE_ID;

-- The current load window of every Module: the end of the last recorded window is the start of the next.
CREATE OR REPLACE VIEW <% database %>.OMD_REPORTING.VW_LOAD_WINDOWS AS
SELECT
    m.MODULE_ID,
    m.MODULE_CODE,
    m.DATA_OBJECT_SOURCE,
    m.DATA_OBJECT_TARGET,
    sc.MODULE_INSTANCE_ID AS LAST_MODULE_INSTANCE_ID,
    sc.INSERT_TIMESTAMP   AS LAST_LOAD_TIMESTAMP,
    sc.START_VALUE        AS LAST_START_VALUE,
    sc.END_VALUE          AS LAST_END_VALUE
FROM <% database %>.OMD.MODULE m
LEFT JOIN <% database %>.OMD.SOURCE_CONTROL sc ON m.MODULE_ID = sc.MODULE_ID
WHERE m.MODULE_ID <> 0
QUALIFY ROW_NUMBER() OVER (PARTITION BY m.MODULE_ID ORDER BY sc.SOURCE_CONTROL_ID DESC NULLS LAST) = 1;

-- Modules that failed in the last three months, with their average duration and failure count.
CREATE OR REPLACE VIEW <% database %>.OMD_REPORTING.VW_MODULE_FAILURES AS
SELECT
    m.MODULE_CODE,
    m.MODULE_DESCRIPTION,
    AVG(DATEDIFF(second, mi.START_TIMESTAMP, mi.END_TIMESTAMP)) AS AVG_EXECUTION_SECONDS,
    SUM(IFF(mi.EXECUTION_STATUS_CODE = 'Failed', 1, 0)) AS COUNT_ERRORS
FROM <% database %>.OMD.MODULE m
JOIN <% database %>.OMD.MODULE_INSTANCE mi ON m.MODULE_ID = mi.MODULE_ID
WHERE mi.START_TIMESTAMP > DATEADD(month, -3, SYSDATE())
GROUP BY m.MODULE_CODE, m.MODULE_DESCRIPTION
HAVING SUM(IFF(mi.EXECUTION_STATUS_CODE = 'Failed', 1, 0)) > 0;

-- Instances that have been executing for more than an hour.
CREATE OR REPLACE VIEW <% database %>.OMD_REPORTING.VW_EXCEPTIONS_LONG_RUNNING_PROCESSES AS
SELECT 'Batch' AS INSTANCE_TYPE, bi.BATCH_INSTANCE_ID AS INSTANCE_ID, b.BATCH_CODE AS CODE, bi.START_TIMESTAMP, DATEDIFF(minute, bi.START_TIMESTAMP, SYSDATE()) AS MINUTES_RUNNING
FROM <% database %>.OMD.BATCH_INSTANCE bi
JOIN <% database %>.OMD.BATCH b ON bi.BATCH_ID = b.BATCH_ID
WHERE bi.EXECUTION_STATUS_CODE = 'Executing' AND bi.START_TIMESTAMP < DATEADD(hour, -1, SYSDATE())
UNION ALL
SELECT 'Module', mi.MODULE_INSTANCE_ID, m.MODULE_CODE, mi.START_TIMESTAMP, DATEDIFF(minute, mi.START_TIMESTAMP, SYSDATE())
FROM <% database %>.OMD.MODULE_INSTANCE mi
JOIN <% database %>.OMD.MODULE m ON mi.MODULE_ID = m.MODULE_ID
WHERE mi.EXECUTION_STATUS_CODE = 'Executing' AND mi.START_TIMESTAMP < DATEADD(hour, -1, SYSDATE());

